// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {V4LegBase, ICampaignV2View, IFeeSplitterLegV2, IPonsV2CurveLeg} from "./V4LegBase.sol";
import {IPoolManagerMin, PoolKey, V4SwapParams, V4Delta} from "./interfaces/IUniV4.sol";
import {IERC20} from "./interfaces/IPons.sol";

/// The trustless buy-and-burn bot (v3: one crank per block). Dual-phase:
///
///   curve phase  — fee ETH market-buys the token directly on the pons
///                  bonding curve (public buy(), native quote)
///   v4 phase     — after graduation, the leg swaps on the Uniswap v4
///                  pool via the PoolManager directly (unlock/callback,
///                  no router) — proven third-party-allowed on fork
///
/// Either way the purchase — and any token-side fees — goes to the dead
/// address. No owner, no operator, no off switch: anyone may crank,
/// nobody can stop it. Per-crank ETH is capped AND cranks are limited to
/// one per block, so the cap is a real per-block bound rather than a
/// per-call one; big accumulations take several blocks.
contract BurnLegV3 is V4LegBase {
    using V4Delta for int256;

    address public constant DEAD = 0x000000000000000000000000000000000000dEaD;
    uint256 public constant MAX_ETH_PER_CRANK = 0.2 ether;

    uint256 public totalEthSpent;
    uint256 public totalTokensBurned;

    /// One crank per block. The per-crank ETH cap only bounds extraction
    /// if it cannot be looped inside a single transaction; without this,
    /// a sandwicher who is also the cranker drains the whole balance 0.2
    /// ETH at a time in one tx. Cross-block bracketing on a 0.1 s L2 is
    /// still possible but pays the full round-trip each block.
    uint256 public lastCrankBlock;

    error CrankedThisBlock();

    event Burned(uint256 ethIn, uint256 tokensBurned, bool viaCurve);

    constructor(address initializer_, IPoolManagerMin poolManager_, address memeHook_)
        V4LegBase(initializer_, poolManager_, memeHook_) {}

    /// Permissionless burn round.
    function crank() external {
        if (!campaign.launched()) revert NotLaunched();
        if (lastCrankBlock == block.number) revert CrankedThisBlock();
        lastCrankBlock = block.number;
        address token = campaign.token();
        _claimBoth(token);

        uint256 burnedNow = 0;

        // token-side fees burn directly
        uint256 tb = IERC20(token).balanceOf(address(this));
        if (tb > 0) {
            IERC20(token).transfer(DEAD, tb);
            burnedNow += tb;
        }

        // ETH-side fees buy-and-burn, capped per crank
        uint256 eb = address(this).balance;
        uint256 amt = eb > MAX_ETH_PER_CRANK ? MAX_ETH_PER_CRANK : eb;
        bool viaCurve = false;
        if (amt > 0) {
            IPonsV2CurveLeg curve = IPonsV2CurveLeg(campaign.curve());
            if (!curve.graduated()) {
                // curve buy is atomic with the crank; the launch-window
                // snipe tax is long gone by the time fees exist
                viaCurve = true;
                curve.buy{value: amt}(amt, 0, address(this));
            } else {
                _unlock(abi.encode(token, amt));
            }
            totalEthSpent += amt;
            uint256 bought = IERC20(token).balanceOf(address(this));
            if (bought > 0) {
                IERC20(token).transfer(DEAD, bought);
                burnedNow += bought;
            }
        }

        totalTokensBurned += burnedNow;
        emit Burned(amt, burnedNow, viaCurve);
    }

    function _handleUnlock(bytes calldata data) internal override returns (bytes memory) {
        (address token, uint256 ethIn) = abi.decode(data, (address, uint256));
        PoolKey memory k = _poolKey(token);
        int256 delta = poolManager.swap(
            k,
            V4SwapParams({zeroForOne: true, amountSpecified: -int256(ethIn), sqrtPriceLimitX96: MIN_SQRT}),
            ""
        );
        _settleDelta(k, delta);
        return "";
    }
}

src/Campaign.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IPonsFactory, IPonsLocker, IERC20, PonsTokenMeta} from "./interfaces/IPons.sol";
import {FeeSplitter} from "./FeeSplitter.sol";

/// One community-pooled token launch on pons (Robinhood Chain).
///
/// The contract IS the token's creator: backers deposit ETH; once the goal is
/// met the pooled balance becomes the creator's initial buy — which pons
/// executes on the launch block, snipe-exempt by the launchpad's own rules —
/// and tokens land here for pro-rata pull-claims. Creator fees route to an
/// immutable FeeSplitter from birth.
///
/// Design rules (the money-audit constitution):
///   - The platform NEVER holds funds. No owner, no admin, no pause, no
///     upgrade. The only privileged address is `creator`, whose only powers
///     are launching EARLY (before deadline) and cancelling an unfunded raise.
///   - Every post-launch action (launch after deadline, claims, refunds,
///     fee collection, fee distribution) is a permissionless crank — nothing
///     depends on prooflaunch infrastructure being alive.
///   - Funds can never be stranded: if the launch hasn't happened by
///     deadline + GRACE, refunds open unconditionally.
///
/// Lifecycle:
///   Open --(goal met, creator early OR anyone after deadline)--> Launched
///   Open --(deadline passed, goal unmet)---------------------> refunds
///   Open --(deadline + GRACE passed, not launched)-----------> refunds
///   Open --(creator cancel before any launch)----------------> refunds
contract Campaign {
    uint256 public constant GRACE = 3 days;

    // ── immutable campaign parameters ────────────────────────────────
    address public immutable creator;
    IPonsFactory public immutable factory;
    uint256 public immutable goal;          // wei; launchable at/above this
    uint256 public immutable minDeposit;    // per backer
    uint256 public immutable maxDeposit;    // per backer (0 = uncapped)
    uint256 public immutable maxBackers;    // slots (0 = uncapped)
    uint256 public immutable deadline;      // unix ts
    uint256 public immutable launchConfigId;
    uint256 public immutable dexId;
    FeeSplitter public immutable feeSplitter;

    // ── token metadata (fixed at creation — what backers signed up for) ─
    PonsTokenMeta internal meta;

    // ── state ────────────────────────────────────────────────────────
    mapping(address => uint256) public contributionOf;
    uint256 public totalRaised;
    uint256 public backerCount;
    bool public launched;
    bool public cancelled;
    address public token;
    address public locker;
    uint256 public tokensAtLaunch;      // claimable pool snapshot
    uint256 public totalRaisedAtLaunch; // share denominator, frozen at launch
    mapping(address => bool) public tokensClaimed;

    // ── events (the indexer's source of truth) ───────────────────────
    event Deposited(address indexed backer, uint256 amount, uint256 totalRaised);
    event Withdrawn(address indexed backer, uint256 amount, uint256 totalRaised);
    event Launch(address indexed token, uint256 pooledBuy, uint256 tokensReceived);
    event TokensClaimed(address indexed backer, uint256 amount);
    event Refunded(address indexed backer, uint256 amount);
    event Cancelled();

    error BadState();
    error BadAmount();
    error SlotsFull();
    error PastDeadline();
    error NotLaunchable();
    error NotRefundable();
    error OnlyCreator();
    error EthSend();
    error Reentrancy();

    uint256 private _lock = 1;
    modifier nonReentrant() {
        if (_lock != 1) revert Reentrancy();
        _lock = 2;
        _;
        _lock = 1;
    }

    constructor(
        address creator_,
        IPonsFactory factory_,
        uint256 goal_,
        uint256 minDeposit_,
        uint256 maxDeposit_,
        uint256 maxBackers_,
        uint256 deadline_,
        uint256 launchConfigId_,
        uint256 dexId_,
        PonsTokenMeta memory meta_,
        uint16 backerBps_,
        address[] memory legRecipients_,
        uint16[] memory legBps_
    ) {
        if (goal_ == 0 || deadline_ <= block.timestamp) revert BadAmount();
        creator = creator_;
        factory = factory_;
        goal = goal_;
        minDeposit = minDeposit_;
        maxDeposit = maxDeposit_;
        maxBackers = maxBackers_;
        deadline = deadline_;
        launchConfigId = launchConfigId_;
        dexId = dexId_;
        feeSplitter = new FeeSplitter(address(this), backerBps_, legRecipients_, legBps_);
        meta = meta_;
        // fee routing is decided here, once, forever
        meta.feeWallet = address(feeSplitter);
    }

    // ── funding phase ────────────────────────────────────────────────

    function deposit() external payable nonReentrant {
        if (launched || cancelled) revert BadState();
        if (block.timestamp >= deadline) revert PastDeadline();
        uint256 newContribution = contributionOf[msg.sender] + msg.value;
        if (msg.value == 0 || newContribution < minDeposit) revert BadAmount();
        if (maxDeposit != 0 && newContribution > maxDeposit) revert BadAmount();
        if (contributionOf[msg.sender] == 0) {
            if (maxBackers != 0 && backerCount >= maxBackers) revert SlotsFull();
            backerCount += 1;
        }
        contributionOf[msg.sender] = newContribution;
        totalRaised += msg.value;
        emit Deposited(msg.sender, msg.value, totalRaised);
    }

    /// Your money is yours until the launch tx fires. Full-exit only —
    /// partial withdrawals reopen min-deposit gaming.
    function withdraw() external nonReentrant {
        if (launched) revert BadState();
        uint256 amount = contributionOf[msg.sender];
        if (amount == 0) revert BadAmount();
        contributionOf[msg.sender] = 0;
        totalRaised -= amount;
        backerCount -= 1;
        emit Withdrawn(msg.sender, amount, totalRaised);
        _send(msg.sender, amount);
    }

    // ── launch ───────────────────────────────────────────────────────

    /// Creator may launch any time once the goal is met. After the deadline,
    /// ANYONE may launch a goal-met campaign — a funded raise cannot be
    /// held hostage by an absent creator.
    function launch() external nonReentrant {
        if (launched || cancelled) revert BadState();
        if (totalRaised < goal) revert NotLaunchable();
        if (msg.sender != creator && block.timestamp < deadline) revert NotLaunchable();
        if (block.timestamp > deadline + GRACE) revert NotLaunchable(); // refunds own this window now

        launched = true;
        totalRaisedAtLaunch = totalRaised;
        locker = factory.locker();

        uint256 pooled = address(this).balance;
        address t = factory.launchToken{value: pooled}(
            meta,
            launchConfigId,
            dexId,
            bytes32(uint256(uint160(address(this))))
        );
        token = t;
        // pons delivers the initial-buy tokens to the feeWallet (the
        // splitter), not to the caller — sweep them home atomically. In this
        // same tx nothing else can have accrued to the splitter, so this is
        // exactly the launch allocation and never fee flow.
        feeSplitter.drainTo(address(this), t);
        tokensAtLaunch = IERC20(t).balanceOf(address(this));
        emit Launch(t, pooled, tokensAtLaunch);
    }

    // ── post-launch: pull claims + permissionless cranks ─────────────

    function claimTokens() external nonReentrant {
        if (!launched) revert BadState();
        if (tokensClaimed[msg.sender]) revert BadAmount();
        uint256 contribution = contributionOf[msg.sender];
        if (contribution == 0) revert BadAmount();
        tokensClaimed[msg.sender] = true;
        uint256 share = (tokensAtLaunch * contribution) / totalRaisedAtLaunch;
        emit TokensClaimed(msg.sender, share);
        if (!IERC20(token).transfer(msg.sender, share)) revert EthSend();
    }

    /// The locker's collectFees is deployer-gated; this contract is the
    /// deployer. Wrapping it keeps fee collection permissionless.
    function pokeCollect() external {
        IPonsLocker(locker).collectFees(token);
    }

    // ── failure paths — funds can never be stranded ──────────────────

    /// Creator may cancel an un-launched raise early (opens refunds).
    function cancel() external {
        if (msg.sender != creator) revert OnlyCreator();
        if (launched || cancelled) revert BadState();
        cancelled = true;
        emit Cancelled();
    }

    /// Refundable when: cancelled; or deadline passed with goal unmet; or
    /// deadline + GRACE passed without a launch (unconditional escape hatch).
    function refundable() public view returns (bool) {
        if (launched) return false;
        if (cancelled) return true;
        if (block.timestamp >= deadline && totalRaised < goal) return true;
        if (block.timestamp > deadline + GRACE) return true;
        return false;
    }

    function refund() external nonReentrant {
        if (!refundable()) revert NotRefundable();
        uint256 amount = contributionOf[msg.sender];
        if (amount == 0) revert BadAmount();
        contributionOf[msg.sender] = 0;
        totalRaised -= amount;
        emit Refunded(msg.sender, amount);
        _send(msg.sender, amount);
    }

    // ── views ────────────────────────────────────────────────────────

    function tokenMeta() external view returns (PonsTokenMeta memory) {
        return meta;
    }

    function _send(address to, uint256 amount) internal {
        (bool ok, ) = to.call{value: amount}("");
        if (!ok) revert EthSend();
    }
}

src/CampaignFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Campaign} from "./Campaign.sol";
import {BurnLeg, IUniV3FactoryMin, ICampaignView, IFeeSplitterLeg} from "./BurnLeg.sol";
import {FeedLPLeg} from "./FeedLPLeg.sol";
import {LegDeployer} from "./LegDeployer.sol";
import {IPonsFactory, PonsTokenMeta} from "./interfaces/IPons.sol";

/// Deploys Campaign + FeeSplitter pairs (and optional bot legs) and
/// enforces the platform's split floor. This is the ONLY place platform
/// policy lives; once a campaign is deployed, nothing here can touch it.
///
/// v2: creator bot legs, carved from the backer share — the RHC twin of
/// the SOL bot stack:
///   - burnBps: deploys an ownerless BurnLeg (buy-and-burn from fees)
///   - lpBps: deploys an ownerless FeedLPLeg (protocol-owned liquidity,
///     locked by construction — the leg has no withdraw)
///   - vault legs: any recipients the creator names (marketing / DAO /
///     treasury wallets…) — the FeeSplitter's pull-based legs support
///     them natively
contract CampaignFactory {
    address public immutable platformFeeRecipient;
    address public immutable holderRewardsRecipient;
    uint16 public immutable platformBps;      // e.g. 700 = 7%
    uint16 public immutable holderRewardsBps; // e.g. 300 = 3%

    // Bot-leg wiring (pons trades on Uniswap-v3-style pools)
    address public immutable weth;
    IUniV3FactoryMin public immutable v3Factory;
    uint24 public immutable poolFee;
    LegDeployer public immutable legDeployer; // keeps this contract under EIP-170

    event CampaignCreated(
        address indexed campaign,
        address indexed creator,
        address feeSplitter,
        uint256 goal,
        uint256 deadline,
        string symbol
    );
    event BotLegs(address indexed campaign, address burnLeg, uint16 burnBps, address lpLeg, uint16 lpBps, uint16 vaultBpsTotal);

    error LegOverflow();
    error LengthMismatch();

    Campaign[] public campaigns;

    constructor(
        address platformFeeRecipient_,
        address holderRewardsRecipient_,
        uint16 platformBps_,
        uint16 holderRewardsBps_,
        address weth_,
        IUniV3FactoryMin v3Factory_,
        uint24 poolFee_,
        LegDeployer legDeployer_
    ) {
        platformFeeRecipient = platformFeeRecipient_;
        holderRewardsRecipient = holderRewardsRecipient_;
        platformBps = platformBps_;
        holderRewardsBps = holderRewardsBps_;
        weth = weth_;
        v3Factory = v3Factory_;
        poolFee = poolFee_;
        legDeployer = legDeployer_;
    }

    /// Backers receive whatever the platform legs and the creator's bot
    /// legs don't take: 10000 − platform − rewards − burn − vaults.
    function createCampaign(
        IPonsFactory ponsFactory,
        uint256 goal,
        uint256 minDeposit,
        uint256 maxDeposit,
        uint256 maxBackers,
        uint256 deadline,
        uint256 launchConfigId,
        uint256 dexId,
        PonsTokenMeta calldata meta,
        uint16 burnBps,
        uint16 lpBps,
        address[] calldata vaultRecipients,
        uint16[] calldata vaultBps
    ) external returns (Campaign campaign) {
        if (vaultRecipients.length != vaultBps.length) revert LengthMismatch();

        uint256 reserved = uint256(platformBps) + holderRewardsBps + burnBps + lpBps;
        for (uint256 i = 0; i < vaultBps.length; i++) reserved += vaultBps[i];
        if (reserved > 10_000) revert LegOverflow();
        uint16 backerBps = uint16(10_000 - reserved);

        // Optional bot legs — deployed first (the splitter needs their
        // addresses as legs), wired to the campaign right after.
        BurnLeg burnLeg = BurnLeg(address(0));
        if (burnBps > 0) {
            burnLeg = legDeployer.deployBurn(weth, v3Factory, poolFee);
        }
        FeedLPLeg lpLeg = FeedLPLeg(address(0));
        if (lpBps > 0) {
            lpLeg = legDeployer.deployLp(weth, v3Factory, poolFee);
        }

        uint256 legCount = 2 + vaultRecipients.length + (burnBps > 0 ? 1 : 0) + (lpBps > 0 ? 1 : 0);
        address[] memory legs = new address[](legCount);
        uint16[] memory legBpsArr = new uint16[](legCount);
        uint256 n = 0;
        legs[n] = holderRewardsRecipient; legBpsArr[n++] = holderRewardsBps;
        if (burnBps > 0) { legs[n] = address(burnLeg); legBpsArr[n++] = burnBps; }
        if (lpBps > 0) { legs[n] = address(lpLeg); legBpsArr[n++] = lpBps; }
        for (uint256 i = 0; i < vaultRecipients.length; i++) {
            legs[n] = vaultRecipients[i]; legBpsArr[n++] = vaultBps[i];
        }
        // platform leg LAST — the splitter's dust-absorber slot
        legs[n] = platformFeeRecipient; legBpsArr[n++] = platformBps;

        campaign = new Campaign(
            msg.sender,
            ponsFactory,
            goal,
            minDeposit,
            maxDeposit,
            maxBackers,
            deadline,
            launchConfigId,
            dexId,
            meta,
            backerBps,
            legs,
            legBpsArr
        );

        if (burnBps > 0) {
            burnLeg.init(ICampaignView(address(campaign)), IFeeSplitterLeg(address(campaign.feeSplitter())));
        }
        if (lpBps > 0) {
            lpLeg.init(ICampaignView(address(campaign)), IFeeSplitterLeg(address(campaign.feeSplitter())));
        }

        campaigns.push(campaign);
        emit CampaignCreated(
            address(campaign), msg.sender, address(campaign.feeSplitter()),
            goal, deadline, meta.symbol
        );
        {
            uint16 vaultTotal = 0;
            for (uint256 i = 0; i < vaultBps.length; i++) vaultTotal += vaultBps[i];
            emit BotLegs(address(campaign), address(burnLeg), burnBps, address(lpLeg), lpBps, vaultTotal);
        }
    }

    function campaignCount() external view returns (uint256) {
        return campaigns.length;
    }
}

