// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {CampaignV2} from "./CampaignV2.sol";
import {IERC20} from "./interfaces/IPons.sol";
import {IPonsV2Factory, IPonsV2LaunchAndBuy} from "./interfaces/IPonsV2.sol";
import {IPoolManagerMin, IV4StateView} from "./interfaces/IUniV4.sol";
import {PonsTokenMeta} from "./interfaces/IPons.sol";
import {LegDeployerV2} from "./LegDeployerV2.sol";
import {BurnLegV2} from "./BurnLegV2.sol";
import {FeedLPLegV2} from "./FeedLPLegV2.sol";
import {ICampaignV2View, IFeeSplitterLegV2, IPonsV2FactoryLegView} from "./V4LegBase.sol";

/// v6 — v5 (tax + trustless v4 bot legs) plus the creation buy-in:
/// an immutable creation fee paid with createCampaign, forwarded straight
/// to the platform recipient (never held here). Spam control, not revenue
/// — the goal-based model already starves junk raises, the fee just stops
/// free-roll board flooding. Waiver hooks are baked in but dormant:
/// deploy with feeWaiverToken = 0 now; once the platform token launches
/// on RHC, redeploy with (token, threshold) and holders create free —
/// the check is an on-chain balance read, enforced by the contract
/// rather than by our server (the SOL waiver, minus the trust).
contract CampaignFactoryV4 {
    address public immutable platformFeeRecipient;
    address public immutable holderRewardsRecipient;
    uint16 public immutable platformBps;      // 700 = 7%
    uint16 public immutable holderRewardsBps; // 300 = 3%

    IPonsV2Factory public immutable ponsFactory;
    IPonsV2LaunchAndBuy public immutable ponsLaunchAndBuy;
    address public immutable ponsFeeEscrow;
    IPoolManagerMin public immutable poolManager;
    address public immutable memeHook;
    IV4StateView public immutable stateView;
    LegDeployerV2 public immutable legDeployer; // keeps this contract under EIP-170

    uint256 public immutable creationFee;        // wei, paid with createCampaign
    IERC20 public immutable feeWaiverToken;      // address(0) = waiver disabled
    uint256 public immutable feeWaiverThreshold; // min balance for a free create

    event CampaignCreated(
        address indexed campaign,
        address indexed creator,
        address feeSplitter,
        uint256 goal,
        uint256 deadline,
        string symbol
    );
    event CampaignTerms(address indexed campaign, uint16 creatorTaxBps, bool buybackEnabled, uint16 vaultBpsTotal);
    event BotLegs(address indexed campaign, address burnLeg, uint16 burnBps, address lpLeg, uint16 lpBps);

    error LegOverflow();
    error LengthMismatch();
    error TaxTooHigh();
    error BadFee();

    CampaignV2[] public campaigns;

    constructor(
        address platformFeeRecipient_,
        address holderRewardsRecipient_,
        uint16 platformBps_,
        uint16 holderRewardsBps_,
        IPonsV2Factory ponsFactory_,
        IPonsV2LaunchAndBuy ponsLaunchAndBuy_,
        address ponsFeeEscrow_,
        IPoolManagerMin poolManager_,
        address memeHook_,
        IV4StateView stateView_,
        LegDeployerV2 legDeployer_,
        uint256 creationFee_,
        IERC20 feeWaiverToken_,
        uint256 feeWaiverThreshold_
    ) {
        platformFeeRecipient = platformFeeRecipient_;
        holderRewardsRecipient = holderRewardsRecipient_;
        platformBps = platformBps_;
        holderRewardsBps = holderRewardsBps_;
        ponsFactory = ponsFactory_;
        ponsLaunchAndBuy = ponsLaunchAndBuy_;
        ponsFeeEscrow = ponsFeeEscrow_;
        poolManager = poolManager_;
        memeHook = memeHook_;
        stateView = stateView_;
        legDeployer = legDeployer_;
        creationFee = creationFee_;
        feeWaiverToken = feeWaiverToken_;
        feeWaiverThreshold = feeWaiverThreshold_;
    }

    /// What this caller owes to create — 0 for waiver-qualified holders.
    function creationFeeFor(address creator) public view returns (uint256) {
        if (
            address(feeWaiverToken) != address(0) &&
            feeWaiverThreshold > 0 &&
            feeWaiverToken.balanceOf(creator) >= feeWaiverThreshold
        ) return 0;
        return creationFee;
    }

    function createCampaign(
        uint256 goal,
        uint256 minDeposit,
        uint256 maxDeposit,
        uint256 maxBackers,
        uint256 deadline,
        uint256 launchConfigId,
        uint16 creatorTaxBps,
        bool buybackEnabled,
        PonsTokenMeta calldata meta,
        uint16 burnBps,
        uint16 lpBps,
        address[] calldata vaultRecipients,
        uint16[] calldata vaultBps
    ) external payable returns (CampaignV2 campaign) {
        // exact-fee buy-in, forwarded immediately — this contract never
        // holds a balance
        if (msg.value != creationFeeFor(msg.sender)) revert BadFee();
        if (msg.value > 0) {
            (bool ok, ) = platformFeeRecipient.call{value: msg.value}("");
            if (!ok) revert BadFee();
        }
        if (vaultRecipients.length != vaultBps.length) revert LengthMismatch();
        if (creatorTaxBps > ponsFactory.maxCreatorTaxBps()) revert TaxTooHigh();

        uint256 reserved = uint256(platformBps) + holderRewardsBps + burnBps + lpBps;
        for (uint256 i = 0; i < vaultBps.length; i++) reserved += vaultBps[i];
        if (reserved > 10_000) revert LegOverflow();
        uint16 backerBps = uint16(10_000 - reserved);

        BurnLegV2 burnLeg = BurnLegV2(payable(address(0)));
        if (burnBps > 0) burnLeg = legDeployer.deployBurn(poolManager, memeHook);
        FeedLPLegV2 lpLeg = FeedLPLegV2(payable(address(0)));
        if (lpBps > 0) lpLeg = legDeployer.deployLp(poolManager, memeHook, stateView);

        uint256 legCount = 2 + vaultRecipients.length + (burnBps > 0 ? 1 : 0) + (lpBps > 0 ? 1 : 0);
        address[] memory legs = new address[](legCount);
        uint16[] memory legBpsArr = new uint16[](legCount);
        uint256 n = 0;
        legs[n] = holderRewardsRecipient; legBpsArr[n++] = holderRewardsBps;
        if (burnBps > 0) { legs[n] = address(burnLeg); legBpsArr[n++] = burnBps; }
        if (lpBps > 0) { legs[n] = address(lpLeg); legBpsArr[n++] = lpBps; }
        for (uint256 i = 0; i < vaultRecipients.length; i++) {
            legs[n] = vaultRecipients[i]; legBpsArr[n++] = vaultBps[i];
        }
        // platform leg LAST — the splitter's dust-absorber slot
        legs[n] = platformFeeRecipient; legBpsArr[n++] = platformBps;

        campaign = new CampaignV2(
            msg.sender,
            ponsFactory,
            ponsLaunchAndBuy,
            ponsFeeEscrow,
            goal,
            minDeposit,
            maxDeposit,
            maxBackers,
            deadline,
            launchConfigId,
            creatorTaxBps,
            buybackEnabled,
            meta,
            backerBps,
            legs,
            legBpsArr
        );

        if (burnBps > 0) {
            burnLeg.init(
                ICampaignV2View(address(campaign)),
                IFeeSplitterLegV2(address(campaign.feeSplitter())),
                IPonsV2FactoryLegView(address(ponsFactory))
            );
        }
        if (lpBps > 0) {
            lpLeg.init(
                ICampaignV2View(address(campaign)),
                IFeeSplitterLegV2(address(campaign.feeSplitter())),
                IPonsV2FactoryLegView(address(ponsFactory))
            );
        }

        campaigns.push(campaign);
        emit CampaignCreated(
            address(campaign), msg.sender, address(campaign.feeSplitter()),
            goal, deadline, meta.symbol
        );
        {
            uint16 vaultTotal = 0;
            for (uint256 i = 0; i < vaultBps.length; i++) vaultTotal += vaultBps[i];
            emit CampaignTerms(address(campaign), creatorTaxBps, buybackEnabled, vaultTotal);
        }
        emit BotLegs(address(campaign), address(burnLeg), burnBps, address(lpLeg), lpBps);
    }

    function campaignCount() external view returns (uint256) {
        return campaigns.length;
    }
}

src/CampaignFactoryV5.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {CampaignV3, CampaignParams} from "./CampaignV3.sol";
import {IPonsV2Factory, IPonsV2LaunchAndBuy} from "./interfaces/IPonsV2.sol";
import {IPoolManagerMin, IV4StateView} from "./interfaces/IUniV4.sol";
import {IERC20} from "./interfaces/IPons.sol";
import {LegDeployerV3} from "./LegDeployerV3.sol";
import {BurnLegV3} from "./BurnLegV3.sol";
import {FeedLPLegV3} from "./FeedLPLegV3.sol";
import {ICampaignV2View, IFeeSplitterLegV2, IPonsV2FactoryLegView} from "./V4LegBase.sol";

/// Carries CampaignV3's creation code out of the factory (EIP-170) and
/// gives every campaign its CREATE2 address — the salt is ground
/// client-side until the address ends in the PoolLaunch signature
/// (0x…5EED). The caller (our factory) is baked into the derivation, so
/// only campaigns deployed through the real factory can wear it.
contract CampaignDeployerV3 {
    address public immutable factory;

    error OnlyFactory();

    constructor() {
        factory = msg.sender;
    }

    /// The exact CREATE2 init-code hash for a campaign with these args.
    /// The browser reads this once per configuration, then grinds salts
    /// locally against it — no contract bytecode in the bundle, no
    /// duplicated encoding logic to drift.
    function initCodeHash(
        address creator,
        IPonsV2Factory ponsFactory,
        IPonsV2LaunchAndBuy launchAndBuy,
        address ponsFeeEscrow,
        address equityRouter,
        CampaignParams calldata p,
        uint16 backerBps,
        address[] calldata legs,
        uint16[] calldata legBps
    ) external pure returns (bytes32) {
        return keccak256(
            abi.encodePacked(
                type(CampaignV3).creationCode,
                abi.encode(creator, ponsFactory, launchAndBuy, ponsFeeEscrow, equityRouter, p, backerBps, legs, legBps)
            )
        );
    }

    function deploy(
        bytes32 salt,
        address creator,
        IPonsV2Factory ponsFactory,
        IPonsV2LaunchAndBuy launchAndBuy,
        address ponsFeeEscrow,
        address equityRouter,
        CampaignParams calldata p,
        uint16 backerBps,
        address[] calldata legs,
        uint16[] calldata legBps
    ) external payable returns (CampaignV3 c) {
        if (msg.sender != factory) revert OnlyFactory();
        c = new CampaignV3{salt: salt, value: msg.value}(
            creator, ponsFactory, launchAndBuy, ponsFeeEscrow, equityRouter, p, backerBps, legs, legBps
        );
    }
}

/// v7 factory — the full option surface behind one struct:
///   raises quoted in ETH, USDG, or tokenized stocks (any pons-approved
///   pair) · team rounds with contract-enforced reserved seats · token-
///   gated entry · CREATE2 signature addresses · creator tax · trustless
///   bot legs (native-quoted raises) · creation fee with on-chain holder
///   waiver. Policy lives here and only here; campaigns are untouchable.
contract CampaignFactoryV5 {
    address public immutable platformFeeRecipient;
    address public immutable holderRewardsRecipient;
    uint16 public immutable platformBps;
    uint16 public immutable holderRewardsBps;

    IPonsV2Factory public immutable ponsFactory;
    IPonsV2LaunchAndBuy public immutable ponsLaunchAndBuy;
    address public immutable ponsFeeEscrow;
    IPoolManagerMin public immutable poolManager;
    address public immutable memeHook;
    IV4StateView public immutable stateView;
    LegDeployerV3 public immutable legDeployer;
    CampaignDeployerV3 public immutable campaignDeployer;

    /// One router for every campaign this factory creates. Immutable here
    /// and never caller-supplied: see FeeSplitterV3.
    address public immutable equityRouter;

    uint256 public immutable creationFee;
    IERC20 public immutable feeWaiverToken;
    uint256 public immutable feeWaiverThreshold;

    event CampaignCreated(
        address indexed campaign,
        address indexed creator,
        address feeSplitter,
        uint256 goal,
        uint256 deadline,
        string symbol
    );
    event CampaignTerms(
        address indexed campaign,
        uint16 creatorTaxBps,
        bool buybackEnabled,
        address quoteToken,
        address gateToken,
        uint16 reservedSeats,
        uint16 vaultBpsTotal
    );
    event BotLegs(address indexed campaign, address burnLeg, uint16 burnBps, address lpLeg, uint16 lpBps);

    error LegOverflow();
    error LengthMismatch();
    error TaxTooHigh();
    error BadFee();
    error BotsNeedNativeQuote();
    error BadVault();

    CampaignV3[] public campaigns;

    constructor(
        address platformFeeRecipient_,
        address holderRewardsRecipient_,
        uint16 platformBps_,
        uint16 holderRewardsBps_,
        IPonsV2Factory ponsFactory_,
        IPonsV2LaunchAndBuy ponsLaunchAndBuy_,
        address ponsFeeEscrow_,
        IPoolManagerMin poolManager_,
        address memeHook_,
        IV4StateView stateView_,
        LegDeployerV3 legDeployer_,
        uint256 creationFee_,
        IERC20 feeWaiverToken_,
        uint256 feeWaiverThreshold_,
        address equityRouter_
    ) {
        platformFeeRecipient = platformFeeRecipient_;
        holderRewardsRecipient = holderRewardsRecipient_;
        platformBps = platformBps_;
        holderRewardsBps = holderRewardsBps_;
        ponsFactory = ponsFactory_;
        ponsLaunchAndBuy = ponsLaunchAndBuy_;
        ponsFeeEscrow = ponsFeeEscrow_;
        poolManager = poolManager_;
        memeHook = memeHook_;
        stateView = stateView_;
        legDeployer = legDeployer_;
        campaignDeployer = new CampaignDeployerV3();
        creationFee = creationFee_;
        feeWaiverToken = feeWaiverToken_;
        feeWaiverThreshold = feeWaiverThreshold_;
        equityRouter = equityRouter_;
    }

    function creationFeeFor(address creator) public view returns (uint256) {
        if (
            address(feeWaiverToken) != address(0) &&
            feeWaiverThreshold > 0 &&
            feeWaiverToken.balanceOf(creator) >= feeWaiverThreshold
        ) return 0;
        return creationFee;
    }

    /// msg.value = creationFeeFor(you) + (ERC20-quoted raises only) the
    /// pons launch fee, escrowed into the campaign for launch day and
    /// refunded to you if the raise dies.
    function createCampaign(
        CampaignParams calldata p,
        uint16 burnBps,
        uint16 lpBps,
        address[] calldata vaultRecipients,
        uint16[] calldata vaultBps,
        bytes32 salt
    ) external payable returns (CampaignV3 campaign) {
        if (vaultRecipients.length != vaultBps.length) revert LengthMismatch();
        // A zero vault leg strands its share in the splitter forever: legOwed
        // accrues to address(0) and only address(0) could claim it.
        for (uint256 i = 0; i < vaultRecipients.length; i++) {
            if (vaultRecipients[i] == address(0) || vaultBps[i] == 0) revert BadVault();
        }
        if (p.creatorTaxBps > ponsFactory.maxCreatorTaxBps()) revert TaxTooHigh();
        // v4-leg bots trade the native pool; ERC20-quoted raises defer them
        if (p.quoteToken != address(0) && (burnBps > 0 || lpBps > 0)) revert BotsNeedNativeQuote();

        // exact buy-in + (ERC20 quote) exact pons launch-fee escrow
        uint256 fee = creationFeeFor(msg.sender);
        uint256 launchFeeEscrow = p.quoteToken == address(0) ? 0 : ponsFactory.launchFee();
        if (msg.value != fee + launchFeeEscrow) revert BadFee();
        if (fee > 0) {
            (bool ok, ) = platformFeeRecipient.call{value: fee}("");
            if (!ok) revert BadFee();
        }

        BurnLegV3 burnLeg = BurnLegV3(payable(address(0)));
        if (burnBps > 0) burnLeg = legDeployer.deployBurn(poolManager, memeHook);
        FeedLPLegV3 lpLeg = FeedLPLegV3(payable(address(0)));
        if (lpBps > 0) lpLeg = legDeployer.deployLp(poolManager, memeHook, stateView);

        (uint16 backerBps, address[] memory legs, uint16[] memory legBpsArr) =
            previewLegs(burnBps, lpBps, vaultRecipients, vaultBps, address(burnLeg), address(lpLeg));

        campaign = campaignDeployer.deploy{value: launchFeeEscrow}(
            salt, msg.sender, ponsFactory, ponsLaunchAndBuy, ponsFeeEscrow, equityRouter,
            p, backerBps, legs, legBpsArr
        );

        if (burnBps > 0) {
            burnLeg.init(ICampaignV2View(address(campaign)), IFeeSplitterLegV2(address(campaign.feeSplitter())), IPonsV2FactoryLegView(address(ponsFactory)));
        }
        if (lpBps > 0) {
            lpLeg.init(ICampaignV2View(address(campaign)), IFeeSplitterLegV2(address(campaign.feeSplitter())), IPonsV2FactoryLegView(address(ponsFactory)));
        }

        campaigns.push(campaign);
        emit CampaignCreated(
            address(campaign), msg.sender, address(campaign.feeSplitter()),
            p.goal, p.deadline, p.meta.symbol
        );
        {
            uint16 vaultTotal = 0;
            for (uint256 i = 0; i < vaultBps.length; i++) vaultTotal += vaultBps[i];
            emit CampaignTerms(address(campaign), p.creatorTaxBps, p.buybackEnabled, p.quoteToken, p.gateToken, p.reservedSeats, vaultTotal);
        }
        emit BotLegs(address(campaign), address(burnLeg), burnBps, address(lpLeg), lpBps);
    }

    /// Leg table construction — the ONE implementation, shared by
    /// createCampaign and the vanity preview so they can never drift.
    /// Order is load-bearing: rewards, burn?, lp?, vaults…, platform LAST
    /// (the splitter's dust absorber).
    function previewLegs(
        uint16 burnBps,
        uint16 lpBps,
        address[] calldata vaultRecipients,
        uint16[] calldata vaultBps,
        address burnLeg,
        address lpLeg
    ) public view returns (uint16 backerBps, address[] memory legs, uint16[] memory legBps) {
        uint256 reserved = uint256(platformBps) + holderRewardsBps + burnBps + lpBps;
        for (uint256 i = 0; i < vaultBps.length; i++) reserved += vaultBps[i];
        if (reserved > 10_000) revert LegOverflow();
        backerBps = uint16(10_000 - reserved);

        uint256 legCount = 2 + vaultRecipients.length + (burnBps > 0 ? 1 : 0) + (lpBps > 0 ? 1 : 0);
        legs = new address[](legCount);
        legBps = new uint16[](legCount);
        uint256 n = 0;
        legs[n] = holderRewardsRecipient; legBps[n++] = holderRewardsBps;
        if (burnBps > 0) { legs[n] = burnLeg; legBps[n++] = burnBps; }
        if (lpBps > 0) { legs[n] = lpLeg; legBps[n++] = lpBps; }
        for (uint256 i = 0; i < vaultRecipients.length; i++) {
            legs[n] = vaultRecipients[i]; legBps[n++] = vaultBps[i];
        }
        legs[n] = platformFeeRecipient; legBps[n++] = platformBps;
    }

    /// One read for the browser's salt grinder: the CREATE2 init-code hash
    /// this exact configuration will deploy with. Campaigns WITHOUT bot
    /// legs are fully deterministic. With bot legs, pass the predicted
    /// leg addresses (LegDeployerV2's next CREATE nonces) — if another
    /// bot campaign lands first the prediction shifts and the address
    /// simply misses the signature. Cosmetic only; nothing is at risk.
    function previewInitCodeHash(
        address creator,
        CampaignParams calldata p,
        uint16 burnBps,
        uint16 lpBps,
        address[] calldata vaultRecipients,
        uint16[] calldata vaultBps,
        address predictedBurnLeg,
        address predictedLpLeg
    ) external view returns (bytes32) {
        (uint16 backerBps, address[] memory legs, uint16[] memory legBps) =
            previewLegs(burnBps, lpBps, vaultRecipients, vaultBps, predictedBurnLeg, predictedLpLeg);
        return campaignDeployer.initCodeHash(
            creator, ponsFactory, ponsLaunchAndBuy, ponsFeeEscrow, equityRouter, p, backerBps, legs, legBps
        );
    }

    function campaignCount() external view returns (uint256) {
        return campaigns.length;
    }
}

src/CampaignFactoryV6.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {CampaignV4} from "./CampaignV4.sol";
import {CampaignParams} from "./CampaignV4.sol";
import {IPonsV2Factory, IPonsV2LaunchAndBuy} from "./interfaces/IPonsV2.sol";
import {IPoolManagerMin, IV4StateView} from "./interfaces/IUniV4.sol";
import {IERC20} from "./interfaces/IPons.sol";
import {LegDeployerV3} from "./LegDeployerV3.sol";
import {BurnLegV3} from "./BurnLegV3.sol";
import {FeedLPLegV3} from "./FeedLPLegV3.sol";
import {ICampaignV2View, IFeeSplitterLegV2, IPonsV2FactoryLegView} from "./V4LegBase.sol";

/// Carries CampaignV4's creation code out of the factory (EIP-170) and
/// gives every campaign its CREATE2 address — the salt is ground
/// client-side until the address ends in the PoolLaunch signature
/// (0x…5EED). The caller (our factory) is baked into the derivation, so
/// only campaigns deployed through the real factory can wear it.
contract CampaignDeployerV4 {
    address public immutable factory;

    error OnlyFactory();

    constructor() {
        factory = msg.sender;
    }

    /// The exact CREATE2 init-code hash for a campaign with these args.
    /// The browser reads this once per configuration, then grinds salts
    /// locally against it — no contract bytecode in the bundle, no
    /// duplicated encoding logic to drift.
    function initCodeHash(
        address creator,
        IPonsV2Factory ponsFactory,
        IPonsV2LaunchAndBuy launchAndBuy,
        address ponsFeeEscrow,
        address equityRouter,
        address splitterDeployer,
        CampaignParams calldata p,
        uint16 backerBps,
        address[] calldata legs,
        uint16[] calldata legBps
    ) external pure returns (bytes32) {
        return keccak256(
            abi.encodePacked(
                type(CampaignV4).creationCode,
                abi.encode(creator, ponsFactory, launchAndBuy, ponsFeeEscrow, equityRouter, splitterDeployer, p, backerBps, legs, legBps)
            )
        );
    }

    function deploy(
        bytes32 salt,
        address creator,
        IPonsV2Factory ponsFactory,
        IPonsV2LaunchAndBuy launchAndBuy,
        address ponsFeeEscrow,
        address equityRouter,
        address splitterDeployer,
        CampaignParams calldata p,
        uint16 backerBps,
        address[] calldata legs,
        uint16[] calldata legBps
    ) external payable returns (CampaignV4 c) {
        if (msg.sender != factory) revert OnlyFactory();
        c = new CampaignV4{salt: salt, value: msg.value}(
            creator, ponsFactory, launchAndBuy, ponsFeeEscrow, equityRouter, splitterDeployer, p, backerBps, legs, legBps
        );
    }
}

/// v8 factory — v7 (CampaignFactoryV5) with one change: campaigns get a
/// FeeSplitterV4, so a backer who sells stops earning and the forfeited
/// share flows to the holder-rewards leg (the RewardsVault, once it is the
/// recipient). Everything below this line is the v7 option surface:
///   raises quoted in ETH, USDG, or tokenized stocks (any pons-approved
///   pair) · team rounds with contract-enforced reserved seats · token-
///   gated entry · CREATE2 signature addresses · creator tax · trustless
///   bot legs (native-quoted raises) · creation fee with on-chain holder
///   waiver. Policy lives here and only here; campaigns are untouchable.
contract CampaignFactoryV6 {
    address public immutable platformFeeRecipient;
    address public immutable holderRewardsRecipient;
    uint16 public immutable platformBps;
    uint16 public immutable holderRewardsBps;

    IPonsV2Factory public immutable ponsFactory;
    IPonsV2LaunchAndBuy public immutable ponsLaunchAndBuy;
    address public immutable ponsFeeEscrow;
    IPoolManagerMin public immutable poolManager;
    address public immutable memeHook;
    IV4StateView public immutable stateView;
    LegDeployerV3 public immutable legDeployer;
    CampaignDeployerV4 public immutable campaignDeployer;

    /// One router for every campaign this factory creates. Immutable here
    /// and never caller-supplied: see FeeSplitterV3.
    address public immutable equityRouter;
    /// FeeSplitterV4's creation code lives here, not in the campaign (EIP-170).
    address public immutable splitterDeployer;

    uint256 public immutable creationFee;
    IERC20 public immutable feeWaiverToken;
    uint256 public immutable feeWaiverThreshold;

    event CampaignCreated(
        address indexed campaign,
        address indexed creator,
        address feeSplitter,
        uint256 goal,
        uint256 deadline,
        string symbol
    );
    event CampaignTerms(
        address indexed campaign,
        uint16 creatorTaxBps,
        bool buybackEnabled,
        address quoteToken,
        address gateToken,
        uint16 reservedSeats,
        uint16 vaultBpsTotal
    );
    event BotLegs(address indexed campaign, address burnLeg, uint16 burnBps, address lpLeg, uint16 lpBps);

    error LegOverflow();
    error LengthMismatch();
    error TaxTooHigh();
    error BadFee();
    error BotsNeedNativeQuote();
    error BadVault();

    CampaignV4[] public campaigns;

    constructor(
        address platformFeeRecipient_,
        address holderRewardsRecipient_,
        uint16 platformBps_,
        uint16 holderRewardsBps_,
        IPonsV2Factory ponsFactory_,
        IPonsV2LaunchAndBuy ponsLaunchAndBuy_,
        address ponsFeeEscrow_,
        IPoolManagerMin poolManager_,
        address memeHook_,
        IV4StateView stateView_,
        LegDeployerV3 legDeployer_,
        uint256 creationFee_,
        IERC20 feeWaiverToken_,
        uint256 feeWaiverThreshold_,
        address equityRouter_,
        address splitterDeployer_
    ) {
        platformFeeRecipient = platformFeeRecipient_;
        holderRewardsRecipient = holderRewardsRecipient_;
        platformBps = platformBps_;
        holderRewardsBps = holderRewardsBps_;
        ponsFactory = ponsFactory_;
        ponsLaunchAndBuy = ponsLaunchAndBuy_;
        ponsFeeEscrow = ponsFeeEscrow_;
        poolManager = poolManager_;
        memeHook = memeHook_;
        stateView = stateView_;
        legDeployer = legDeployer_;
        campaignDeployer = new CampaignDeployerV4();
        creationFee = creationFee_;
        feeWaiverToken = feeWaiverToken_;
        feeWaiverThreshold = feeWaiverThreshold_;
        equityRouter = equityRouter_;
        splitterDeployer = splitterDeployer_;
    }

    function creationFeeFor(address creator) public view returns (uint256) {
        if (
            address(feeWaiverToken) != address(0) &&
            feeWaiverThreshold > 0 &&
            feeWaiverToken.balanceOf(creator) >= feeWaiverThreshold
        ) return 0;
        return creationFee;
    }

    /// msg.value = creationFeeFor(you) + (ERC20-quoted raises only) the
    /// pons launch fee, escrowed into the campaign for launch day and
    /// refunded to you if the raise dies.
    function createCampaign(
        CampaignParams calldata p,
        uint16 burnBps,
        uint16 lpBps,
        address[] calldata vaultRecipients,
        uint16[] calldata vaultBps,
        bytes32 salt
    ) external payable returns (CampaignV4 campaign) {
        if (vaultRecipients.length != vaultBps.length) revert LengthMismatch();
        // A zero vault leg strands its share in the splitter forever: legOwed
        // accrues to address(0) and only address(0) could claim it.
        for (uint256 i = 0; i < vaultRecipients.length; i++) {
            if (vaultRecipients[i] == address(0) || vaultBps[i] == 0) revert BadVault();
        }
        if (p.creatorTaxBps > ponsFactory.maxCreatorTaxBps()) revert TaxTooHigh();
        // v4-leg bots trade the native pool; ERC20-quoted raises defer them
        if (p.quoteToken != address(0) && (burnBps > 0 || lpBps > 0)) revert BotsNeedNativeQuote();

        // exact buy-in + (ERC20 quote) exact pons launch-fee escrow
        uint256 fee = creationFeeFor(msg.sender);
        uint256 launchFeeEscrow = p.quoteToken == address(0) ? 0 : ponsFactory.launchFee();
        if (msg.value != fee + launchFeeEscrow) revert BadFee();
        if (fee > 0) {
            (bool ok, ) = platformFeeRecipient.call{value: fee}("");
            if (!ok) revert BadFee();
        }

        BurnLegV3 burnLeg = BurnLegV3(payable(address(0)));
        if (burnBps > 0) burnLeg = legDeployer.deployBurn(poolManager, memeHook);
        FeedLPLegV3 lpLeg = FeedLPLegV3(payable(address(0)));
        if (lpBps > 0) lpLeg = legDeployer.deployLp(poolManager, memeHook, stateView);

        (uint16 backerBps, address[] memory legs, uint16[] memory legBpsArr) =
            previewLegs(burnBps, lpBps, vaultRecipients, vaultBps, address(burnLeg), address(lpLeg));

        campaign = campaignDeployer.deploy{value: launchFeeEscrow}(
            salt, msg.sender, ponsFactory, ponsLaunchAndBuy, ponsFeeEscrow, equityRouter, splitterDeployer,
            p, backerBps, legs, legBpsArr
        );

        if (burnBps > 0) {
            burnLeg.init(ICampaignV2View(address(campaign)), IFeeSplitterLegV2(address(campaign.feeSplitter())), IPonsV2FactoryLegView(address(ponsFactory)));
        }
        if (lpBps > 0) {
            lpLeg.init(ICampaignV2View(address(campaign)), IFeeSplitterLegV2(address(campaign.feeSplitter())), IPonsV2FactoryLegView(address(ponsFactory)));
        }

        campaigns.push(campaign);
        emit CampaignCreated(
            address(campaign), msg.sender, address(campaign.feeSplitter()),
            p.goal, p.deadline, p.meta.symbol
        );
        {
            uint16 vaultTotal = 0;
            for (uint256 i = 0; i < vaultBps.length; i++) vaultTotal += vaultBps[i];
            emit CampaignTerms(address(campaign), p.creatorTaxBps, p.buybackEnabled, p.quoteToken, p.gateToken, p.reservedSeats, vaultTotal);
        }
        emit BotLegs(address(campaign), address(burnLeg), burnBps, address(lpLeg), lpBps);
    }

    /// Leg table construction — the ONE implementation, shared by
    /// createCampaign and the vanity preview so they can never drift.
    /// Order is load-bearing: rewards, burn?, lp?, vaults…, platform LAST
    /// (the splitter's dust absorber).
    function previewLegs(
        uint16 burnBps,
        uint16 lpBps,
        address[] calldata vaultRecipients,
        uint16[] calldata vaultBps,
        address burnLeg,
        address lpLeg
    ) public view returns (uint16 backerBps, address[] memory legs, uint16[] memory legBps) {
        uint256 reserved = uint256(platformBps) + holderRewardsBps + burnBps + lpBps;
        for (uint256 i = 0; i < vaultBps.length; i++) reserved += vaultBps[i];
        if (reserved > 10_000) revert LegOverflow();
        backerBps = uint16(10_000 - reserved);

        uint256 legCount = 2 + vaultRecipients.length + (burnBps > 0 ? 1 : 0) + (lpBps > 0 ? 1 : 0);
        legs = new address[](legCount);
        legBps = new uint16[](legCount);
        uint256 n = 0;
        legs[n] = holderRewardsRecipient; legBps[n++] = holderRewardsBps;
        if (burnBps > 0) { legs[n] = burnLeg; legBps[n++] = burnBps; }
        if (lpBps > 0) { legs[n] = lpLeg; legBps[n++] = lpBps; }
        for (uint256 i = 0; i < vaultRecipients.length; i++) {
            legs[n] = vaultRecipients[i]; legBps[n++] = vaultBps[i];
        }
        legs[n] = platformFeeRecipient; legBps[n++] = platformBps;
    }

    /// One read for the browser's salt grinder: the CREATE2 init-code hash
    /// this exact configuration will deploy with. Campaigns WITHOUT bot
    /// legs are fully deterministic. With bot legs, pass the predicted
    /// leg addresses (LegDeployerV2's next CREATE nonces) — if another
    /// bot campaign lands first the prediction shifts and the address
    /// simply misses the signature. Cosmetic only; nothing is at risk.
    function previewInitCodeHash(
        address creator,
        CampaignParams calldata p,
        uint16 burnBps,
        uint16 lpBps,
        address[] calldata vaultRecipients,
        uint16[] calldata vaultBps,
        address predictedBurnLeg,
        address predictedLpLeg
    ) external view returns (bytes32) {
        (uint16 backerBps, address[] memory legs, uint16[] memory legBps) =
            previewLegs(burnBps, lpBps, vaultRecipients, vaultBps, predictedBurnLeg, predictedLpLeg);
        return campaignDeployer.initCodeHash(
            creator, ponsFactory, ponsLaunchAndBuy, ponsFeeEscrow, equityRouter, splitterDeployer, p, backerBps, legs, legBps
        );
    }

    function campaignCount() external view returns (uint256) {
        return campaigns.length;
    }
}

src/CampaignV2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC20, PonsTokenMeta} from "./interfaces/IPons.sol";
import {IPonsV2Factory, IPonsV2LaunchAndBuy, IPonsV2FeeEscrow, IPonsV2Curve, PonsV2LaunchParams} from "./interfaces/IPonsV2.sol";
import {FeeSplitterV2} from "./FeeSplitterV2.sol";

/// One community-pooled token launch on pons V2 (curve → locked Uniswap v4).
/// Same money-audit constitution as V1's Campaign — the platform never holds
/// funds, no owner/admin/pause/upgrade, every post-launch action is a
/// permissionless crank, funds can never be stranded — plus the V2 features:
///
///   - creatorTaxBps: the pons trading tax, chosen at creation, immutable,
///     earned by the campaign's FeeSplitter (i.e. by the backers)
///   - buybackEnabled: pons' native buyback flywheel for this token
///   - the pooled buy goes through pons' LaunchAndBuy in ONE transaction:
///     token + curve created and bought before any external actor can act
///   - oversized raises: a pooled buy crossing the graduation threshold is
///     partially refunded BY THE CURVE to this contract; the refund is
///     snapshotted as excessAtLaunch and claimed pro-rata with tokens
contract CampaignV2 {
    uint256 public constant GRACE = 3 days;

    // ── immutable campaign parameters ────────────────────────────────
    address public immutable creator;
    IPonsV2Factory public immutable ponsFactory;
    IPonsV2LaunchAndBuy public immutable ponsLaunchAndBuy;
    uint256 public immutable goal;
    uint256 public immutable minDeposit;
    uint256 public immutable maxDeposit;    // 0 = uncapped
    uint256 public immutable maxBackers;    // 0 = uncapped
    uint256 public immutable deadline;
    uint256 public immutable launchConfigId;
    uint16 public immutable creatorTaxBps;
    bool public immutable buybackEnabled;
    FeeSplitterV2 public immutable feeSplitter;

    // ── token metadata (fixed at creation — what backers signed up for) ─
    PonsTokenMeta internal meta; // feeWallet field unused on V2

    // ── state ────────────────────────────────────────────────────────
    mapping(address => uint256) public contributionOf;
    uint256 public totalRaised;
    uint256 public backerCount;
    bool public launched;
    bool public cancelled;
    address public token;
    address public curve;
    uint256 public tokensAtLaunch;      // claimable pool snapshot
    uint256 public excessAtLaunch;      // curve refund on oversized raises
    uint256 public totalRaisedAtLaunch; // share denominator, frozen at launch
    mapping(address => bool) public tokensClaimed;

    event Deposited(address indexed backer, uint256 amount, uint256 totalRaised);
    event Withdrawn(address indexed backer, uint256 amount, uint256 totalRaised);
    event Launch(address indexed token, address curve, uint256 pooledBuy, uint256 tokensReceived, uint256 excessRefunded);
    event TokensClaimed(address indexed backer, uint256 tokenAmount, uint256 excessEth);
    event Refunded(address indexed backer, uint256 amount);
    event Cancelled();

    error BadState();
    error BadAmount();
    error SlotsFull();
    error PastDeadline();
    error NotLaunchable();
    error NotRefundable();
    error OnlyCreator();
    error EthSend();
    error Reentrancy();

    uint256 private _lock = 1;
    modifier nonReentrant() {
        if (_lock != 1) revert Reentrancy();
        _lock = 2;
        _;
        _lock = 1;
    }

    constructor(
        address creator_,
        IPonsV2Factory ponsFactory_,
        IPonsV2LaunchAndBuy ponsLaunchAndBuy_,
        address ponsFeeEscrow_,
        uint256 goal_,
        uint256 minDeposit_,
        uint256 maxDeposit_,
        uint256 maxBackers_,
        uint256 deadline_,
        uint256 launchConfigId_,
        uint16 creatorTaxBps_,
        bool buybackEnabled_,
        PonsTokenMeta memory meta_,
        uint16 backerBps_,
        address[] memory legRecipients_,
        uint16[] memory legBps_
    ) {
        if (goal_ == 0 || deadline_ <= block.timestamp) revert BadAmount();
        creator = creator_;
        ponsFactory = ponsFactory_;
        ponsLaunchAndBuy = ponsLaunchAndBuy_;
        goal = goal_;
        minDeposit = minDeposit_;
        maxDeposit = maxDeposit_;
        maxBackers = maxBackers_;
        deadline = deadline_;
        launchConfigId = launchConfigId_;
        creatorTaxBps = creatorTaxBps_;
        buybackEnabled = buybackEnabled_;
        feeSplitter = new FeeSplitterV2(
            address(this),
            IPonsV2FeeEscrow(ponsFeeEscrow_),
            backerBps_,
            legRecipients_,
            legBps_
        );
        meta = meta_;
    }

    /// The curve refunds excess here on oversized raises; nothing else is
    /// expected, but stray donations only ever add to backer value.
    receive() external payable {}

    // ── funding phase ────────────────────────────────────────────────

    function deposit() external payable nonReentrant {
        if (launched || cancelled) revert BadState();
        if (block.timestamp >= deadline) revert PastDeadline();
        uint256 newContribution = contributionOf[msg.sender] + msg.value;
        if (msg.value == 0 || newContribution < minDeposit) revert BadAmount();
        if (maxDeposit != 0 && newContribution > maxDeposit) revert BadAmount();
        if (contributionOf[msg.sender] == 0) {
            if (maxBackers != 0 && backerCount >= maxBackers) revert SlotsFull();
            backerCount += 1;
        }
        contributionOf[msg.sender] = newContribution;
        totalRaised += msg.value;
        emit Deposited(msg.sender, msg.value, totalRaised);
    }

    /// Your money is yours until the launch tx fires. Full-exit only.
    function withdraw() external nonReentrant {
        if (launched) revert BadState();
        uint256 amount = contributionOf[msg.sender];
        if (amount == 0) revert BadAmount();
        contributionOf[msg.sender] = 0;
        totalRaised -= amount;
        backerCount -= 1;
        emit Withdrawn(msg.sender, amount, totalRaised);
        _send(msg.sender, amount);
    }

    // ── launch ───────────────────────────────────────────────────────

    /// Creator may launch once the goal is met; anyone may after the
    /// deadline. One transaction: create token + curve, pooled buy lands
    /// here, fee routing to the splitter fixed forever.
    function launch() external nonReentrant {
        if (launched || cancelled) revert BadState();
        if (totalRaised < goal) revert NotLaunchable();
        if (msg.sender != creator && block.timestamp < deadline) revert NotLaunchable();
        if (block.timestamp > deadline + GRACE) revert NotLaunchable();

        launched = true;
        totalRaisedAtLaunch = totalRaised;

        uint256 pooled = address(this).balance;
        uint256 fee = ponsFactory.launchFee();
        // Read the economics hash in the SAME tx — pons refuses the launch
        // if the config changed between read and execution.
        bytes32 econ = ponsFactory.previewLaunchEconomics(launchConfigId, address(0));

        PonsTokenMeta memory m = meta;
        PonsV2LaunchParams memory p = PonsV2LaunchParams({
            name: m.name,
            symbol: m.symbol,
            logo: m.logo,
            description: m.description,
            socials: m.socials,
            creatorFeeRecipient: address(feeSplitter),
            creatorTaxBps: creatorTaxBps,
            buybackEnabled: buybackEnabled,
            expectedEconomics: econ,
            salt: bytes32(uint256(uint160(address(this))))
        });

        // minTokensOut = 0 is safe here: the curve is CREATED in this same
        // transaction — no one can trade it before our buy.
        (address t, address c, ) = ponsLaunchAndBuy.launchAndBuy{value: pooled}(
            p, launchConfigId, address(0), pooled - fee, 0, address(this), new address[](0)
        );
        token = t;
        curve = c;
        tokensAtLaunch = IERC20(t).balanceOf(address(this));
        // Oversized raise: the curve refunds whatever crossed graduation.
        excessAtLaunch = address(this).balance;
        emit Launch(t, c, pooled, tokensAtLaunch, excessAtLaunch);
    }

    // ── post-launch: pull claims + permissionless cranks ─────────────

    /// Claim your token share — and, on oversized raises, your share of the
    /// ETH the curve refunded at launch.
    function claimTokens() external nonReentrant {
        if (!launched) revert BadState();
        if (tokensClaimed[msg.sender]) revert BadAmount();
        uint256 contribution = contributionOf[msg.sender];
        if (contribution == 0) revert BadAmount();
        tokensClaimed[msg.sender] = true;
        uint256 share = (tokensAtLaunch * contribution) / totalRaisedAtLaunch;
        uint256 excess = (excessAtLaunch * contribution) / totalRaisedAtLaunch;
        emit TokensClaimed(msg.sender, share, excess);
        if (!IERC20(token).transfer(msg.sender, share)) revert EthSend();
        if (excess > 0) _send(msg.sender, excess);
    }

    /// Permissionless fee crank. pons V2 gates the curve→escrow sweep to
    /// its own feeSweepOperator bot (verified on fork: NotFeeSweepOperator)
    /// — the try lets us piggyback if pons ever opens it, and their bot
    /// sweeps continuously anyway since the pons protocol share rides the
    /// same sweep. Once fees hit the escrow, harvest() is fully
    /// permissionless: pull + account, nobody can block it.
    function pokeHarvest() external {
        address c = curve;
        if (c != address(0)) {
            try IPonsV2Curve(c).sweepFees(0) {} catch {}
        }
        feeSplitter.harvest();
    }

    // ── failure paths — funds can never be stranded ──────────────────

    function cancel() external {
        if (msg.sender != creator) revert OnlyCreator();
        if (launched || cancelled) revert BadState();
        cancelled = true;
        emit Cancelled();
    }

    function refundable() public view returns (bool) {
        if (launched) return false;
        if (cancelled) return true;
        if (block.timestamp >= deadline && totalRaised < goal) return true;
        if (block.timestamp > deadline + GRACE) return true;
        return false;
    }

    function refund() external nonReentrant {
        if (!refundable()) revert NotRefundable();
        uint256 amount = contributionOf[msg.sender];
        if (amount == 0) revert BadAmount();
        contributionOf[msg.sender] = 0;
        totalRaised -= amount;
        emit Refunded(msg.sender, amount);
        _send(msg.sender, amount);
    }

    // ── views ────────────────────────────────────────────────────────

    function tokenMeta() external view returns (PonsTokenMeta memory) {
        return meta;
    }

    function _send(address to, uint256 amount) internal {
        (bool ok, ) = to.call{value: amount}("");
        if (!ok) revert EthSend();
    }
}

src/CampaignV3.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC20, PonsTokenMeta} from "./interfaces/IPons.sol";
import {IPonsV2Factory, IPonsV2LaunchAndBuy, IPonsV2FeeEscrow, IPonsV2Curve, PonsV2LaunchParams} from "./interfaces/IPonsV2.sol";
import {IEquityRouter} from "./interfaces/IEquityRouter.sol";
import {FeeSplitterV3} from "./FeeSplitterV3.sol";

interface IERC20Quote {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function balanceOf(address) external view returns (uint256);
}

/// Everything the raise can be, in one immutable bundle. A struct because
/// the option surface outgrew a sane argument list.
struct CampaignParams {
    uint256 goal;           // in quote units
    uint256 minDeposit;
    uint256 maxDeposit;     // 0 = uncapped
    uint256 maxBackers;     // 0 = open (unlimited backers)
    uint256 deadline;
    uint256 launchConfigId;
    uint16 creatorTaxBps;
    bool buybackEnabled;
    address quoteToken;     // 0 = native ETH; else a pons-approved pair (USDG, tokenized stocks…)
    address gateToken;      // 0 = ungated; else must hold >= gateMinBalance to back
    uint256 gateMinBalance;
    uint16 reservedSeats;   // team round: seats only allowlisted wallets may take
    address[] allowlist;    // wallets eligible for reserved seats
    address payoutAsset;    // creator's DEFAULT for fee claims (0 = ETH); every claimer may override
    PonsTokenMeta meta;
}

/// v7 campaign — CampaignV2's constitution (platform never holds funds,
/// no owner/admin/pause/upgrade, permissionless cranks, refunds as code)
/// plus the full option surface:
///
///   TEAM ROUNDS   reservedSeats of maxBackers are claimable only by
///                 allowlisted wallets; the public's remaining seats are
///                 guaranteed — the contract enforces the split, not us
///   TOKEN GATING  optional "hold >= N of gateToken to back" — utility
///                 for the platform token, anti-bot armor for creators
///   ERC20 QUOTES  raises pooled in any pons-approved pair token (USDG,
///                 tokenized stocks): deposits via approve+depositToken,
///                 the launch fee (native ETH) is escrowed by the creator
///                 at creation and refunded to them if the raise dies
contract CampaignV3 {
    uint256 public constant GRACE = 3 days;

    // ── immutables ───────────────────────────────────────────────────
    address public immutable creator;
    IPonsV2Factory public immutable ponsFactory;
    IPonsV2LaunchAndBuy public immutable ponsLaunchAndBuy;
    uint256 public immutable goal;
    uint256 public immutable minDeposit;
    uint256 public immutable maxDeposit;
    uint256 public immutable maxBackers;
    uint256 public immutable deadline;
    uint256 public immutable launchConfigId;
    uint16 public immutable creatorTaxBps;
    bool public immutable buybackEnabled;
    address public immutable quoteToken;
    address public immutable payoutAsset; // UI default only — never enforced
    address public immutable gateToken;
    uint256 public immutable gateMinBalance;
    uint16 public immutable reservedSeats;
    FeeSplitterV3 public immutable feeSplitter;
    uint256 public immutable launchFeeEscrowed; // native ETH held for pons' launch fee (ERC20 quotes)

    PonsTokenMeta internal meta;

    // ── state ────────────────────────────────────────────────────────
    mapping(address => bool) public allowlisted;
    mapping(address => uint8) public seatBucket; // 0 none · 1 public · 2 reserved
    uint256 public publicSeatsUsed;
    uint256 public reservedSeatsUsed;

    mapping(address => uint256) public contributionOf;
    uint256 public totalRaised;
    uint256 public backerCount;
    bool public launched;
    bool public cancelled;
    bool public launchFeeRefunded;
    address public token;
    address public curve;
    uint256 public tokensAtLaunch;
    uint256 public excessAtLaunch;      // curve refund (quote units) on oversized raises
    uint256 public totalRaisedAtLaunch;
    mapping(address => bool) public tokensClaimed;

    event Deposited(address indexed backer, uint256 amount, uint256 totalRaised, uint8 bucket);
    event Withdrawn(address indexed backer, uint256 amount, uint256 totalRaised);
    event Launch(address indexed token, address curve, uint256 pooledBuy, uint256 tokensReceived, uint256 excessRefunded);
    event TokensClaimed(address indexed backer, uint256 tokenAmount, uint256 excessQuote);
    event Refunded(address indexed backer, uint256 amount);
    event LaunchFeeRefunded(address indexed creator, uint256 amount);
    event Cancelled();

    error BadState();
    error BadAmount();
    error SlotsFull();
    error PastDeadline();
    error NotLaunchable();
    error NotRefundable();
    error OnlyCreator();
    error PayFailed();
    error Reentrancy();
    error WrongAsset();
    error GateFailed();

    uint256 private _lock = 1;
    modifier nonReentrant() {
        if (_lock != 1) revert Reentrancy();
        _lock = 2;
        _;
        _lock = 1;
    }

    constructor(
        address creator_,
        IPonsV2Factory ponsFactory_,
        IPonsV2LaunchAndBuy ponsLaunchAndBuy_,
        address ponsFeeEscrow_,
        address equityRouter_,
        CampaignParams memory p,
        uint16 backerBps_,
        address[] memory legRecipients_,
        uint16[] memory legBps_
    ) payable {
        if (p.goal == 0 || p.deadline <= block.timestamp) revert BadAmount();
        // A native raise below pons' launch fee can fill and then never
        // launch (pooled - fee underflows) — trapping backers until grace.
        if (p.quoteToken == address(0) && p.goal < ponsFactory_.launchFee()) revert BadAmount();
        // reserved seats only mean something in a slotted raise, and can't
        // exceed the seat count
        if (p.reservedSeats > 0 && (p.maxBackers == 0 || p.reservedSeats > p.maxBackers)) revert BadAmount();
        creator = creator_;
        ponsFactory = ponsFactory_;
        ponsLaunchAndBuy = ponsLaunchAndBuy_;
        goal = p.goal;
        minDeposit = p.minDeposit;
        maxDeposit = p.maxDeposit;
        maxBackers = p.maxBackers;
        deadline = p.deadline;
        launchConfigId = p.launchConfigId;
        creatorTaxBps = p.creatorTaxBps;
        buybackEnabled = p.buybackEnabled;
        quoteToken = p.quoteToken;
        payoutAsset = p.payoutAsset;
        gateToken = p.gateToken;
        gateMinBalance = p.gateMinBalance;
        reservedSeats = p.reservedSeats;
        // ERC20-quoted raises: the pons launch fee is native ETH, escrowed
        // here by the creator at creation (factory forwards it); refunded
        // to the creator if the raise never launches.
        launchFeeEscrowed = msg.value;
        for (uint256 i = 0; i < p.allowlist.length; i++) allowlisted[p.allowlist[i]] = true;
        feeSplitter = new FeeSplitterV3(
            address(this), IPonsV2FeeEscrow(ponsFeeEscrow_), backerBps_, legRecipients_, legBps_,
            IEquityRouter(equityRouter_)
        );
        meta = p.meta;
    }

    receive() external payable {}

    // ── funding phase ────────────────────────────────────────────────

    /// Native-quoted deposits.
    function deposit() external payable nonReentrant {
        if (quoteToken != address(0)) revert WrongAsset();
        _deposit(msg.value);
    }

    /// ERC20-quoted deposits (approve first).
    function depositToken(uint256 amount) external nonReentrant {
        if (quoteToken == address(0)) revert WrongAsset();
        if (!IERC20Quote(quoteToken).transferFrom(msg.sender, address(this), amount)) revert PayFailed();
        _deposit(amount);
    }

    function _deposit(uint256 amount) internal {
        if (launched || cancelled) revert BadState();
        if (block.timestamp >= deadline) revert PastDeadline();
        uint256 newContribution = contributionOf[msg.sender] + amount;
        if (amount == 0 || newContribution < minDeposit) revert BadAmount();
        if (maxDeposit != 0 && newContribution > maxDeposit) revert BadAmount();

        if (contributionOf[msg.sender] == 0) {
            // token gate applies at entry
            if (gateToken != address(0) && IERC20(gateToken).balanceOf(msg.sender) < gateMinBalance) {
                revert GateFailed();
            }
            // seat assignment: allowlisted wallets fill reserved seats
            // first, everyone else competes for the public ones — and the
            // public's share is a guarantee, not a leftover
            if (maxBackers != 0) {
                if (allowlisted[msg.sender] && reservedSeatsUsed < reservedSeats) {
                    reservedSeatsUsed += 1;
                    seatBucket[msg.sender] = 2;
                } else {
                    if (publicSeatsUsed >= maxBackers - reservedSeats) revert SlotsFull();
                    publicSeatsUsed += 1;
                    seatBucket[msg.sender] = 1;
                }
            } else {
                seatBucket[msg.sender] = 1;
            }
            backerCount += 1;
        }
        contributionOf[msg.sender] = newContribution;
        totalRaised += amount;
        emit Deposited(msg.sender, amount, totalRaised, seatBucket[msg.sender]);
    }

    /// Full-exit withdrawal, any time before launch. Frees the seat back
    /// to its bucket.
    function withdraw() external nonReentrant {
        if (launched) revert BadState();
        uint256 amount = contributionOf[msg.sender];
        if (amount == 0) revert BadAmount();
        contributionOf[msg.sender] = 0;
        totalRaised -= amount;
        backerCount -= 1;
        if (seatBucket[msg.sender] == 2) reservedSeatsUsed -= 1;
        else if (seatBucket[msg.sender] == 1 && maxBackers != 0) publicSeatsUsed -= 1;
        seatBucket[msg.sender] = 0;
        emit Withdrawn(msg.sender, amount, totalRaised);
        _payQuote(msg.sender, amount);
    }

    // ── launch ───────────────────────────────────────────────────────

    function launch() external nonReentrant {
        if (launched || cancelled) revert BadState();
        if (totalRaised < goal) revert NotLaunchable();
        if (msg.sender != creator && block.timestamp < deadline) revert NotLaunchable();
        if (block.timestamp > deadline + GRACE) revert NotLaunchable();

        launched = true;
        totalRaisedAtLaunch = totalRaised;

        uint256 fee = ponsFactory.launchFee();
        bytes32 econ = ponsFactory.previewLaunchEconomics(launchConfigId, quoteToken);

        PonsTokenMeta memory m = meta;
        PonsV2LaunchParams memory p = PonsV2LaunchParams({
            name: m.name,
            symbol: m.symbol,
            logo: m.logo,
            description: m.description,
            socials: m.socials,
            creatorFeeRecipient: address(feeSplitter),
            creatorTaxBps: creatorTaxBps,
            buybackEnabled: buybackEnabled,
            expectedEconomics: econ,
            salt: bytes32(uint256(uint160(address(this))))
        });

        address t;
        address c;
        if (quoteToken == address(0)) {
            uint256 pooled = address(this).balance;
            if (pooled <= fee) revert NotLaunchable(); // pons raised its fee past the pool: grace → refunds
            (t, c, ) = ponsLaunchAndBuy.launchAndBuy{value: pooled}(
                p, launchConfigId, address(0), pooled - fee, 0, address(this), new address[](0)
            );
            token = t;
            curve = c;
            excessAtLaunch = address(this).balance;
        } else {
            uint256 pooled = IERC20Quote(quoteToken).balanceOf(address(this));
            if (launchFeeEscrowed < fee) revert NotLaunchable(); // pons raised its fee: grace → refunds
            IERC20Quote(quoteToken).approve(address(ponsLaunchAndBuy), pooled);
            (t, c, ) = ponsLaunchAndBuy.launchAndBuy{value: fee}(
                p, launchConfigId, quoteToken, pooled, 0, address(this), new address[](0)
            );
            token = t;
            curve = c;
            IERC20Quote(quoteToken).approve(address(ponsLaunchAndBuy), 0);
            excessAtLaunch = IERC20Quote(quoteToken).balanceOf(address(this));
            // The escrow was sized at creation; pons' fee may have dropped
            // since. Whatever native is left is the creator's, and nothing
            // else in an ERC20 raise ever legitimately holds ETH here.
            _returnNativeToCreator();
        }
        tokensAtLaunch = IERC20(t).balanceOf(address(this));
        emit Launch(t, c, totalRaisedAtLaunch, tokensAtLaunch, excessAtLaunch);
    }

    // ── post-launch ──────────────────────────────────────────────────

    function claimTokens() external nonReentrant {
        if (!launched) revert BadState();
        if (tokensClaimed[msg.sender]) revert BadAmount();
        uint256 contribution = contributionOf[msg.sender];
        if (contribution == 0) revert BadAmount();
        tokensClaimed[msg.sender] = true;
        uint256 share = (tokensAtLaunch * contribution) / totalRaisedAtLaunch;
        uint256 excess = (excessAtLaunch * contribution) / totalRaisedAtLaunch;
        emit TokensClaimed(msg.sender, share, excess);
        if (!IERC20(token).transfer(msg.sender, share)) revert PayFailed();
        if (excess > 0) _payQuote(msg.sender, excess);
    }

    /// Permissionless fee crank (sweep is pons-operator-gated; harvest
    /// is always ours to run).
    function pokeHarvest() external {
        address c = curve;
        if (c != address(0)) {
            try IPonsV2Curve(c).sweepFees(0) {} catch {}
        }
        feeSplitter.harvest();
    }

    // ── failure paths ────────────────────────────────────────────────

    function cancel() external {
        if (msg.sender != creator) revert OnlyCreator();
        if (launched || cancelled) revert BadState();
        cancelled = true;
        emit Cancelled();
    }

    function refundable() public view returns (bool) {
        if (launched) return false;
        if (cancelled) return true;
        if (block.timestamp >= deadline && totalRaised < goal) return true;
        if (block.timestamp > deadline + GRACE) return true;
        return false;
    }

    function refund() external nonReentrant {
        if (!refundable()) revert NotRefundable();
        uint256 amount = contributionOf[msg.sender];
        if (amount == 0) revert BadAmount();
        contributionOf[msg.sender] = 0;
        totalRaised -= amount;
        emit Refunded(msg.sender, amount);
        _payQuote(msg.sender, amount);
    }

    /// ERC20-quoted raises only: return the creator's native escrow when
    /// the raise is dead, and sweep any native left after launch (fee
    /// surplus, stray sends). Never callable while a raise is live — the
    /// escrow is what launch spends. Native-quoted raises hold backers'
    /// ETH and revert here unconditionally.
    function refundLaunchFee() external nonReentrant {
        if (quoteToken == address(0)) revert NotRefundable();
        if (!launched && !refundable()) revert NotRefundable();
        if (address(this).balance == 0) revert NotRefundable();
        _returnNativeToCreator();
    }

    function _returnNativeToCreator() internal {
        uint256 amount = address(this).balance;
        if (amount == 0) return;
        launchFeeRefunded = true;
        emit LaunchFeeRefunded(creator, amount);
        (bool ok, ) = creator.call{value: amount}("");
        if (!ok) revert PayFailed();
    }

    // ── views + internals ────────────────────────────────────────────

    function tokenMeta() external view returns (PonsTokenMeta memory) {
        return meta;
    }

    function _payQuote(address to, uint256 amount) internal {
        if (quoteToken == address(0)) {
            (bool ok, ) = to.call{value: amount}("");
            if (!ok) revert PayFailed();
        } else {
            if (!IERC20Quote(quoteToken).transfer(to, amount)) revert PayFailed();
        }
    }
}

src/CampaignV4.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC20, PonsTokenMeta} from "./interfaces/IPons.sol";
import {IPonsV2Factory, IPonsV2LaunchAndBuy, IPonsV2FeeEscrow, IPonsV2Curve, PonsV2LaunchParams} from "./interfaces/IPonsV2.sol";
import {IEquityRouter} from "./interfaces/IEquityRouter.sol";
import {FeeSplitterV4} from "./FeeSplitterV4.sol";
import {ISplitterDeployerV4} from "./SplitterDeployerV4.sol";
import {CampaignParams} from "./CampaignV3.sol";

interface IERC20Quote {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function balanceOf(address) external view returns (uint256);
}

/// CampaignV3 with a FeeSplitterV4: the fee stream follows the tokens
/// (see FeeSplitterV4.sol). Everything else is CampaignV3 verbatim —
/// same params, same lifecycle, same constructor shape, so the CREATE2
/// grinder and the deployer encoding are unchanged. v8 factory only.
contract CampaignV4 {
    uint256 public constant GRACE = 3 days;

    // ── immutables ───────────────────────────────────────────────────
    address public immutable creator;
    IPonsV2Factory public immutable ponsFactory;
    IPonsV2LaunchAndBuy public immutable ponsLaunchAndBuy;
    uint256 public immutable goal;
    uint256 public immutable minDeposit;
    uint256 public immutable maxDeposit;
    uint256 public immutable maxBackers;
    uint256 public immutable deadline;
    uint256 public immutable launchConfigId;
    uint16 public immutable creatorTaxBps;
    bool public immutable buybackEnabled;
    address public immutable quoteToken;
    address public immutable payoutAsset; // UI default only — never enforced
    address public immutable gateToken;
    uint256 public immutable gateMinBalance;
    uint16 public immutable reservedSeats;
    FeeSplitterV4 public immutable feeSplitter;
    uint256 public immutable launchFeeEscrowed; // native ETH held for pons' launch fee (ERC20 quotes)

    PonsTokenMeta internal meta;

    // ── state ────────────────────────────────────────────────────────
    mapping(address => bool) public allowlisted;
    mapping(address => uint8) public seatBucket; // 0 none · 1 public · 2 reserved
    uint256 public publicSeatsUsed;
    uint256 public reservedSeatsUsed;

    mapping(address => uint256) public contributionOf;
    uint256 public totalRaised;
    uint256 public backerCount;
    bool public launched;
    bool public cancelled;
    bool public launchFeeRefunded;
    address public token;
    address public curve;
    uint256 public tokensAtLaunch;
    uint256 public excessAtLaunch;      // curve refund (quote units) on oversized raises
    uint256 public totalRaisedAtLaunch;
    mapping(address => bool) public tokensClaimed;
    /// Pre-launch lock, chosen by the backer when they take their seat and
    /// visible on the roster before anyone else commits. The tokens never
    /// leave THIS contract until the date: no second contract, no locker
    /// brand to trust, nothing an admin could shorten (there is no admin).
    /// Only ever extendable. Cleared by a pre-launch withdraw (they left).
    /// A locked seat still earns its full fee share — FeeSplitterV4 counts
    /// unclaimed tokens as held.
    mapping(address => uint64) public lockUntil;
    /// Fat-finger guard: a typo must not become a permanent lock.
    uint64 public constant MAX_LOCK = 4 * 365 days;
    /// Excess quote (oversized raise refund) is paid on claimTokens; a
    /// locked backer can take it early instead of waiting for their tokens.
    mapping(address => bool) public excessClaimed;

    event Deposited(address indexed backer, uint256 amount, uint256 totalRaised, uint8 bucket);
    event Withdrawn(address indexed backer, uint256 amount, uint256 totalRaised);
    event Launch(address indexed token, address curve, uint256 pooledBuy, uint256 tokensReceived, uint256 excessRefunded);
    event TokensClaimed(address indexed backer, uint256 tokenAmount, uint256 excessQuote);
    event Refunded(address indexed backer, uint256 amount);
    event LaunchFeeRefunded(address indexed creator, uint256 amount);
    event Cancelled();
    event Locked(address indexed backer, uint64 until);

    error BadState();
    error BadAmount();
    error SlotsFull();
    error PastDeadline();
    error NotLaunchable();
    error NotRefundable();
    error OnlyCreator();
    error PayFailed();
    error Reentrancy();
    error WrongAsset();
    error GateFailed();
    error StillLocked();
    error LockNotLonger();
    error LockTooLong();

    uint256 private _lock = 1;
    modifier nonReentrant() {
        if (_lock != 1) revert Reentrancy();
        _lock = 2;
        _;
        _lock = 1;
    }

    constructor(
        address creator_,
        IPonsV2Factory ponsFactory_,
        IPonsV2LaunchAndBuy ponsLaunchAndBuy_,
        address ponsFeeEscrow_,
        address equityRouter_,
        address splitterDeployer_,
        CampaignParams memory p,
        uint16 backerBps_,
        address[] memory legRecipients_,
        uint16[] memory legBps_
    ) payable {
        if (p.goal == 0 || p.deadline <= block.timestamp) revert BadAmount();
        // A native raise below pons' launch fee can fill and then never
        // launch (pooled - fee underflows) — trapping backers until grace.
        if (p.quoteToken == address(0) && p.goal < ponsFactory_.launchFee()) revert BadAmount();
        // reserved seats only mean something in a slotted raise, and can't
        // exceed the seat count
        if (p.reservedSeats > 0 && (p.maxBackers == 0 || p.reservedSeats > p.maxBackers)) revert BadAmount();
        creator = creator_;
        ponsFactory = ponsFactory_;
        ponsLaunchAndBuy = ponsLaunchAndBuy_;
        goal = p.goal;
        minDeposit = p.minDeposit;
        maxDeposit = p.maxDeposit;
        maxBackers = p.maxBackers;
        deadline = p.deadline;
        launchConfigId = p.launchConfigId;
        creatorTaxBps = p.creatorTaxBps;
        buybackEnabled = p.buybackEnabled;
        quoteToken = p.quoteToken;
        payoutAsset = p.payoutAsset;
        gateToken = p.gateToken;
        gateMinBalance = p.gateMinBalance;
        reservedSeats = p.reservedSeats;
        // ERC20-quoted raises: the pons launch fee is native ETH, escrowed
        // here by the creator at creation (factory forwards it); refunded
        // to the creator if the raise never launches.
        launchFeeEscrowed = msg.value;
        for (uint256 i = 0; i < p.allowlist.length; i++) allowlisted[p.allowlist[i]] = true;
        // Forfeited backer shares go to the holder-rewards leg. The factory's
        // leg table is load-bearing here: rewards is ALWAYS legs[0]
        // (CampaignFactoryV6.previewLegs), platform always last.
        if (legRecipients_.length == 0) revert BadAmount();
        // Deployed through a satellite so the splitter's creation code does
        // not ride inside ours (EIP-170). msg.sender there is this address.
        feeSplitter = ISplitterDeployerV4(splitterDeployer_).deploy(
            IPonsV2FeeEscrow(ponsFeeEscrow_), backerBps_, legRecipients_, legBps_,
            IEquityRouter(equityRouter_), legRecipients_[0]
        );
        meta = p.meta;
    }

    receive() external payable {}

    // ── funding phase ────────────────────────────────────────────────

    /// Native-quoted deposits.
    function deposit() external payable nonReentrant {
        if (quoteToken != address(0)) revert WrongAsset();
        _deposit(msg.value);
    }

    /// ERC20-quoted deposits (approve first).
    /// deposit(), plus a promise: my tokens stay in this contract until
    /// `until`. Set at seat time so every later backer can see it.
    function depositLocked(uint64 until) external payable nonReentrant {
        if (quoteToken != address(0)) revert WrongAsset();
        _setLock(until);
        _deposit(msg.value);
    }

    /// depositToken(), locked. See depositLocked.
    function depositTokenLocked(uint256 amount, uint64 until) external nonReentrant {
        if (quoteToken == address(0)) revert WrongAsset();
        _setLock(until);
        if (!IERC20Quote(quoteToken).transferFrom(msg.sender, address(this), amount)) revert PayFailed();
        _deposit(amount);
    }

    /// Longer, never shorter. Any time before the tokens are claimed.
    function extendLock(uint64 until) external {
        if (contributionOf[msg.sender] == 0 || tokensClaimed[msg.sender]) revert BadState();
        _setLock(until);
    }

    function _setLock(uint64 until) internal {
        if (until <= block.timestamp || until <= lockUntil[msg.sender]) revert LockNotLonger();
        if (until > block.timestamp + MAX_LOCK) revert LockTooLong();
        lockUntil[msg.sender] = until;
        emit Locked(msg.sender, until);
    }

    function depositToken(uint256 amount) external nonReentrant {
        if (quoteToken == address(0)) revert WrongAsset();
        if (!IERC20Quote(quoteToken).transferFrom(msg.sender, address(this), amount)) revert PayFailed();
        _deposit(amount);
    }

    function _deposit(uint256 amount) internal {
        if (launched || cancelled) revert BadState();
        if (block.timestamp >= deadline) revert PastDeadline();
        uint256 newContribution = contributionOf[msg.sender] + amount;
        if (amount == 0 || newContribution < minDeposit) revert BadAmount();
        if (maxDeposit != 0 && newContribution > maxDeposit) revert BadAmount();

        if (contributionOf[msg.sender] == 0) {
            // token gate applies at entry
            if (gateToken != address(0) && IERC20(gateToken).balanceOf(msg.sender) < gateMinBalance) {
                revert GateFailed();
            }
            // seat assignment: allowlisted wallets fill reserved seats
            // first, everyone else competes for the public ones — and the
            // public's share is a guarantee, not a leftover
            if (maxBackers != 0) {
                if (allowlisted[msg.sender] && reservedSeatsUsed < reservedSeats) {
                    reservedSeatsUsed += 1;
                    seatBucket[msg.sender] = 2;
                } else {
                    if (publicSeatsUsed >= maxBackers - reservedSeats) revert SlotsFull();
                    publicSeatsUsed += 1;
                    seatBucket[msg.sender] = 1;
                }
            } else {
                seatBucket[msg.sender] = 1;
            }
            backerCount += 1;
        }
        contributionOf[msg.sender] = newContribution;
        totalRaised += amount;
        emit Deposited(msg.sender, amount, totalRaised, seatBucket[msg.sender]);
    }

    /// Full-exit withdrawal, any time before launch. Frees the seat back
    /// to its bucket.
    function withdraw() external nonReentrant {
        if (launched) revert BadState();
        uint256 amount = contributionOf[msg.sender];
        if (amount == 0) revert BadAmount();
        contributionOf[msg.sender] = 0;
        totalRaised -= amount;
        backerCount -= 1;
        if (seatBucket[msg.sender] == 2) reservedSeatsUsed -= 1;
        else if (seatBucket[msg.sender] == 1 && maxBackers != 0) publicSeatsUsed -= 1;
        seatBucket[msg.sender] = 0;
        lockUntil[msg.sender] = 0; // the promise went with the seat
        emit Withdrawn(msg.sender, amount, totalRaised);
        _payQuote(msg.sender, amount);
    }

    // ── launch ───────────────────────────────────────────────────────

    function launch() external nonReentrant {
        if (launched || cancelled) revert BadState();
        if (totalRaised < goal) revert NotLaunchable();
        if (msg.sender != creator && block.timestamp < deadline) revert NotLaunchable();
        if (block.timestamp > deadline + GRACE) revert NotLaunchable();

        launched = true;
        totalRaisedAtLaunch = totalRaised;

        uint256 fee = ponsFactory.launchFee();
        bytes32 econ = ponsFactory.previewLaunchEconomics(launchConfigId, quoteToken);

        PonsTokenMeta memory m = meta;
        PonsV2LaunchParams memory p = PonsV2LaunchParams({
            name: m.name,
            symbol: m.symbol,
            logo: m.logo,
            description: m.description,
            socials: m.socials,
            creatorFeeRecipient: address(feeSplitter),
            creatorTaxBps: creatorTaxBps,
            buybackEnabled: buybackEnabled,
            expectedEconomics: econ,
            salt: bytes32(uint256(uint160(address(this))))
        });

        address t;
        address c;
        if (quoteToken == address(0)) {
            uint256 pooled = address(this).balance;
            if (pooled <= fee) revert NotLaunchable(); // pons raised its fee past the pool: grace → refunds
            (t, c, ) = ponsLaunchAndBuy.launchAndBuy{value: pooled}(
                p, launchConfigId, address(0), pooled - fee, 0, address(this), new address[](0)
            );
            token = t;
            curve = c;
            excessAtLaunch = address(this).balance;
        } else {
            uint256 pooled = IERC20Quote(quoteToken).balanceOf(address(this));
            if (launchFeeEscrowed < fee) revert NotLaunchable(); // pons raised its fee: grace → refunds
            IERC20Quote(quoteToken).approve(address(ponsLaunchAndBuy), pooled);
            (t, c, ) = ponsLaunchAndBuy.launchAndBuy{value: fee}(
                p, launchConfigId, quoteToken, pooled, 0, address(this), new address[](0)
            );
            token = t;
            curve = c;
            IERC20Quote(quoteToken).approve(address(ponsLaunchAndBuy), 0);
            excessAtLaunch = IERC20Quote(quoteToken).balanceOf(address(this));
            // The escrow was sized at creation; pons' fee may have dropped
            // since. Whatever native is left is the creator's, and nothing
            // else in an ERC20 raise ever legitimately holds ETH here.
            _returnNativeToCreator();
        }
        tokensAtLaunch = IERC20(t).balanceOf(address(this));
        emit Launch(t, c, totalRaisedAtLaunch, tokensAtLaunch, excessAtLaunch);
    }

    // ── post-launch ──────────────────────────────────────────────────

    function claimTokens() external nonReentrant {
        if (!launched) revert BadState();
        if (tokensClaimed[msg.sender]) revert BadAmount();
        if (block.timestamp < lockUntil[msg.sender]) revert StillLocked();
        uint256 contribution = contributionOf[msg.sender];
        if (contribution == 0) revert BadAmount();
        tokensClaimed[msg.sender] = true;
        uint256 share = (tokensAtLaunch * contribution) / totalRaisedAtLaunch;
        uint256 excess = excessClaimed[msg.sender] ? 0 : (excessAtLaunch * contribution) / totalRaisedAtLaunch;
        excessClaimed[msg.sender] = true;
        emit TokensClaimed(msg.sender, share, excess);
        if (!IERC20(token).transfer(msg.sender, share)) revert PayFailed();
        if (excess > 0) _payQuote(msg.sender, excess);
    }

    /// The oversized-raise refund, on its own — so a lock never traps
    /// quote that was always going back to the backer.
    function claimExcess() external nonReentrant {
        if (!launched) revert BadState();
        if (excessClaimed[msg.sender]) revert BadAmount();
        uint256 contribution = contributionOf[msg.sender];
        if (contribution == 0) revert BadAmount();
        excessClaimed[msg.sender] = true;
        uint256 excess = (excessAtLaunch * contribution) / totalRaisedAtLaunch;
        if (excess == 0) revert BadAmount();
        _payQuote(msg.sender, excess);
    }

    /// Permissionless fee crank (sweep is pons-operator-gated; harvest
    /// is always ours to run).
    function pokeHarvest() external {
        address c = curve;
        if (c != address(0)) {
            try IPonsV2Curve(c).sweepFees(0) {} catch {}
        }
        feeSplitter.harvest();
    }

    // ── failure paths ────────────────────────────────────────────────

    function cancel() external {
        if (msg.sender != creator) revert OnlyCreator();
        if (launched || cancelled) revert BadState();
        cancelled = true;
        emit Cancelled();
    }

    function refundable() public view returns (bool) {
        if (launched) return false;
        if (cancelled) return true;
        if (block.timestamp >= deadline && totalRaised < goal) return true;
        if (block.timestamp > deadline + GRACE) return true;
        return false;
    }

    function refund() external nonReentrant {
        if (!refundable()) revert NotRefundable();
        uint256 amount = contributionOf[msg.sender];
        if (amount == 0) revert BadAmount();
        contributionOf[msg.sender] = 0;
        totalRaised -= amount;
        emit Refunded(msg.sender, amount);
        _payQuote(msg.sender, amount);
    }

    /// ERC20-quoted raises only: return the creator's native escrow when
    /// the raise is dead, and sweep any native left after launch (fee
    /// surplus, stray sends). Never callable while a raise is live — the
    /// escrow is what launch spends. Native-quoted raises hold backers'
    /// ETH and revert here unconditionally.
    function refundLaunchFee() external nonReentrant {
        if (quoteToken == address(0)) revert NotRefundable();
        if (!launched && !refundable()) revert NotRefundable();
        if (address(this).balance == 0) revert NotRefundable();
        _returnNativeToCreator();
    }

    function _returnNativeToCreator() internal {
        uint256 amount = address(this).balance;
        if (amount == 0) return;
        launchFeeRefunded = true;
        emit LaunchFeeRefunded(creator, amount);
        (bool ok, ) = creator.call{value: amount}("");
        if (!ok) revert PayFailed();
    }

    // ── views + internals ────────────────────────────────────────────

    function tokenMeta() external view returns (PonsTokenMeta memory) {
        return meta;
    }

    function _payQuote(address to, uint256 amount) internal {
        if (quoteToken == address(0)) {
            (bool ok, ) = to.call{value: amount}("");
            if (!ok) revert PayFailed();
        } else {
            if (!IERC20Quote(quoteToken).transfer(to, amount)) revert PayFailed();
        }
    }
}

src/EquityRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IPoolManagerMin, PoolKey, V4SwapParams, V4Delta} from "./interfaces/IUniV4.sol";

/// ETH in, any asset out — the one primitive behind "get paid in stock".
///
/// Ownerless, stateless between calls, and holds nothing. It exists so a
/// claimer can route their OWN entitlement through a swap in the same
/// transaction that pays them: the protocol always owes ETH, and the
/// recipient decides what lands in their wallet.
///
/// DELIBERATELY PERMISSIONLESS. There is no allowlist of "approved"
/// assets, because an allowlist is an admin, and an admin is the one
/// thing this architecture refuses to have. The caller supplies the
/// PoolKey, so the day Robinhood tokenizes anything new it works here
/// with no deploy, no vote, and no permission. A caller who points this
/// at a bad pool gets a bad price and their own minOut stops it — the
/// risk is theirs and it is bounded by a number they chose.
contract EquityRouter {
    using V4Delta for int256;

    /// v4 MIN_SQRT_PRICE + 1 — the limit for a zeroForOne (ETH → asset) swap.
    uint160 internal constant MIN_SQRT = 4295128740;

    IPoolManagerMin public immutable poolManager;

    /// Set only for the duration of one unlock: authenticates the callback
    /// and doubles as the reentrancy guard. Plain storage, not transient —
    /// this is an Orbit L2 and V4LegBase's live legs use the same pattern;
    /// TSTORE support is not worth assuming for the gas it saves.
    address private _unlocking;

    event Routed(
        address indexed payer,
        address indexed recipient,
        address indexed asset,
        uint256 ethIn,
        uint256 assetOut
    );

    error NotNativePair();
    error NothingIn();
    error BadRecipient();
    error Reentrant();
    error BadCallback();
    error Slippage(uint256 out, uint256 minOut);
    error RefundFailed();

    constructor(IPoolManagerMin poolManager_) {
        poolManager = poolManager_;
    }

    /// Native credits can only land here via `take` on a degenerate pool;
    /// accept them so they can be refunded rather than trapped.
    receive() external payable {}

    /// Swap the full `msg.value` into `key.currency1` and deliver it to
    /// `recipient`. Reverts unless at least `minOut` arrives.
    ///
    /// `key.currency0` MUST be native ETH (address(0)) — v4 sorts address(0)
    /// first, so for any ETH-paired pool the target asset is currency1.
    function routeEthTo(
        PoolKey calldata key,
        uint256 minOut,
        address recipient,
        bytes calldata hookData
    ) external payable returns (uint256 assetOut) {
        if (key.currency0 != address(0)) revert NotNativePair();
        if (msg.value == 0) revert NothingIn();
        if (recipient == address(0)) revert BadRecipient();
        if (_unlocking != address(0)) revert Reentrant();

        _unlocking = address(poolManager);
        bytes memory res = poolManager.unlock(abi.encode(key, msg.value, recipient, hookData));
        _unlocking = address(0);

        assetOut = abi.decode(res, (uint256));
        if (assetOut < minOut) revert Slippage(assetOut, minOut);

        // Exact-input consumes the whole amount, but never let dust stick to
        // an ownerless contract: anything left is the payer's.
        uint256 dust = address(this).balance;
        if (dust > 0) {
            (bool ok, ) = msg.sender.call{value: dust}("");
            if (!ok) revert RefundFailed();
        }

        emit Routed(msg.sender, recipient, key.currency1, msg.value, assetOut);
    }

    function unlockCallback(bytes calldata data) external returns (bytes memory) {
        if (msg.sender != _unlocking || _unlocking == address(0)) revert BadCallback();

        (PoolKey memory key, uint256 amountIn, address recipient, bytes memory hookData) =
            abi.decode(data, (PoolKey, uint256, address, bytes));

        // Negative amountSpecified = exact input.
        int256 delta = poolManager.swap(
            key,
            V4SwapParams({
                zeroForOne: true,
                amountSpecified: -int256(amountIn),
                sqrtPriceLimitX96: MIN_SQRT
            }),
            hookData
        );

        int128 a0 = delta.amount0();
        int128 a1 = delta.amount1();

        // We owe native for what we spent…
        if (a0 < 0) poolManager.settle{value: uint256(uint128(-a0))}();
        // …and a well-formed pool never asks us for the asset on this leg.
        if (a1 < 0) revert NotNativePair();

        // Unspent native (partial fill against the price limit) comes back
        // here and is refunded to the payer by routeEthTo.
        if (a0 > 0) poolManager.take(address(0), address(this), uint256(uint128(a0)));

        uint256 out;
        if (a1 > 0) {
            out = uint256(uint128(a1));
            // Straight to the claimer — the router never custodies the asset.
            poolManager.take(key.currency1, recipient, out);
        }
        return abi.encode(out);
    }
}

src/FeeSplitter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC20} from "./interfaces/IPons.sol";

interface ICampaignShares {
    function contributionOf(address backer) external view returns (uint256);
    function totalRaisedAtLaunch() external view returns (uint256);
    function launched() external view returns (bool);
}

/// Receives the token's creator-fee share from the pons locker (WETH + the
/// launched token — v3 fees accrue in BOTH pool assets) and splits it by
/// immutable basis points:
///
///   - the backer pool (pro-rata to launch-time contributions, read live from
///     the Campaign — no duplicated share table to drift)
///   - fixed legs (platform, $PROOF holder rewards, future bot modules)
///
/// Everything is PULL-based. distribute() is a permissionless crank that only
/// does internal accounting; no external recipient can grief it by reverting,
/// and no operator has to be alive for anyone to get paid. There is no owner,
/// no admin, and no way to change the split after deployment.
contract FeeSplitter {
    ICampaignShares public immutable campaign;
    uint16 public immutable backerBps; // out of 10_000
    address[] public legRecipients;
    uint16[] public legBps;

    // cumulative amounts allocated to the backer pool, per asset
    // (asset address(0) = native ETH)
    mapping(address => uint256) public backerPool;
    // per-leg allocated-but-unclaimed balances: leg => asset => amount
    mapping(address => mapping(address => uint256)) public legOwed;
    // per-backer cumulative claims from the backer pool: backer => asset
    mapping(address => mapping(address => uint256)) public backerClaimed;
    // total balance already accounted for, per asset (so distribute() only
    // touches the delta since last crank)
    mapping(address => uint256) public accounted;

    error NotLaunched();
    error NothingToClaim();
    error LengthMismatch();
    error BpsSum();
    error EthSend();

    constructor(
        address campaign_,
        uint16 backerBps_,
        address[] memory legRecipients_,
        uint16[] memory legBps_
    ) {
        if (legRecipients_.length != legBps_.length) revert LengthMismatch();
        uint256 sum = backerBps_;
        for (uint256 i = 0; i < legBps_.length; i++) sum += legBps_[i];
        if (sum != 10_000) revert BpsSum();
        campaign = ICampaignShares(campaign_);
        backerBps = backerBps_;
        legRecipients = legRecipients_;
        legBps = legBps_;
    }

    receive() external payable {}

    /// pons sends the launch-time initial-buy tokens to the feeWallet (this
    /// contract), not to the launch caller — discovered by fork test, see
    /// spec §8. The Campaign calls this ONCE, inside the same transaction as
    /// launchToken(), to move the launch allocation home before any fees can
    /// have accrued. Campaign-only; safe to call repeatedly (drains balance).
    function drainTo(address to, address asset) external {
        if (msg.sender != address(campaign)) revert NotLaunched();
        uint256 bal = asset == address(0)
            ? address(this).balance
            : IERC20(asset).balanceOf(address(this));
        uint256 unaccounted = bal - accounted[asset];
        if (unaccounted == 0) return;
        if (asset == address(0)) {
            (bool ok, ) = to.call{value: unaccounted}("");
            if (!ok) revert EthSend();
        } else {
            if (!IERC20(asset).transfer(to, unaccounted)) revert EthSend();
        }
    }

    /// Permissionless. Allocates any un-accounted balance of `asset` to the
    /// backer pool and the legs. address(0) = native ETH.
    function distribute(address asset) public {
        uint256 bal = asset == address(0)
            ? address(this).balance
            : IERC20(asset).balanceOf(address(this));
        uint256 delta = bal - accounted[asset];
        if (delta == 0) return;
        accounted[asset] = bal;

        uint256 toBackers = (delta * backerBps) / 10_000;
        backerPool[asset] += toBackers;
        uint256 allocated = toBackers;
        for (uint256 i = 0; i < legRecipients.length; i++) {
            uint256 amt = (delta * legBps[i]) / 10_000;
            // last leg absorbs rounding dust so nothing is stranded
            if (i == legRecipients.length - 1) amt = delta - allocated;
            else allocated += amt;
            legOwed[legRecipients[i]][asset] += amt;
        }
    }

    /// A backer's lifetime entitlement from the backer pool for `asset`.
    function backerEntitlement(address backer, address asset) public view returns (uint256) {
        uint256 total = campaign.totalRaisedAtLaunch();
        if (total == 0) return 0;
        return (backerPool[asset] * campaign.contributionOf(backer)) / total;
    }

    /// Pull a backer's outstanding share of `asset`. Anyone can crank
    /// distribute() first; claim does it implicitly for freshness.
    function claimBacker(address asset) external {
        if (!campaign.launched()) revert NotLaunched();
        distribute(asset);
        uint256 owed = backerEntitlement(msg.sender, asset) - backerClaimed[msg.sender][asset];
        if (owed == 0) revert NothingToClaim();
        backerClaimed[msg.sender][asset] += owed;
        _pay(msg.sender, asset, owed);
    }

    /// Pull a leg's outstanding balance of `asset` (platform, holder rewards…).
    function claimLeg(address asset) external {
        distribute(asset);
        uint256 owed = legOwed[msg.sender][asset];
        if (owed == 0) revert NothingToClaim();
        legOwed[msg.sender][asset] = 0;
        _pay(msg.sender, asset, owed);
    }

    function _pay(address to, address asset, uint256 amount) internal {
        // effects above, interaction last; accounted must shrink with balance
        accounted[asset] -= amount;
        if (asset == address(0)) {
            (bool ok, ) = to.call{value: amount}("");
            if (!ok) revert EthSend();
        } else {
            if (!IERC20(asset).transfer(to, amount)) revert EthSend();
        }
    }

    function legCount() external view returns (uint256) {
        return legRecipients.length;
    }
}

src/FeeSplitterV2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {FeeSplitter} from "./FeeSplitter.sol";
import {IPonsV2FeeEscrow} from "./interfaces/IPonsV2.sol";

interface ICampaignTokenView {
    function token() external view returns (address);
}

/// The V1 FeeSplitter with one addition for pons V2's pull-model: creator
/// fees are credited to this contract inside the pons FeeEscrow (native ETH
/// + the launched token), and `harvest()` — permissionless — pulls them home
/// and runs the internal accounting. Everything else (immutable split,
/// pull-based backer/leg claims, no owner) is inherited unchanged.
contract FeeSplitterV2 is FeeSplitter {
    IPonsV2FeeEscrow public immutable escrow;

    constructor(
        address campaign_,
        IPonsV2FeeEscrow escrow_,
        uint16 backerBps_,
        address[] memory legRecipients_,
        uint16[] memory legBps_
    ) FeeSplitter(campaign_, backerBps_, legRecipients_, legBps_) {
        escrow = escrow_;
    }

    /// Pull everything the escrow owes us, then account for it. Anyone may
    /// crank; claimBacker/claimLeg still work without it (they distribute()
    /// whatever already arrived), so this only ever helps.
    function harvest() external {
        uint256 owedEth = escrow.balanceOf(address(this));
        if (owedEth > 0) escrow.claim(owedEth);
        distribute(address(0));

        address t = ICampaignTokenView(address(campaign)).token();
        if (t != address(0)) {
            uint256 owedTok = escrow.balanceOfToken(address(this), t);
            if (owedTok > 0) escrow.claimToken(t, owedTok);
            distribute(t);
        }
    }
}

src/FeeSplitterV3.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {FeeSplitter} from "./FeeSplitter.sol";
import {IPonsV2FeeEscrow} from "./interfaces/IPonsV2.sol";
import {IEquityRouter} from "./interfaces/IEquityRouter.sol";
import {PoolKey} from "./interfaces/IUniV4.sol";

interface ICampaignAssetsView {
    function token() external view returns (address);
    function quoteToken() external view returns (address);
}

/// FeeSplitterV2's escrow-harvest, made quote-aware: an ERC20-quoted
/// campaign (USDG, tokenized stocks…) earns creator fees in the QUOTE
/// asset + the launched token; a native campaign earns ETH + token.
/// harvest() pulls whichever apply. The per-asset accounting underneath
/// is inherited unchanged — it never cared what the assets were.
contract FeeSplitterV3 is FeeSplitter {
    IPonsV2FeeEscrow public immutable escrow;

    /// Platform-fixed at construction (factory → campaign → here). Only the
    /// NATIVE entitlement can be routed: the splitter owes ETH, and the
    /// recipient chooses what lands in their wallet. Nothing here ever
    /// holds an equity; the asset is taken straight to the claimer.
    IEquityRouter public immutable equityRouter;

    event ClaimedAs(address indexed who, address indexed asset, uint256 ethIn, uint256 assetOut, bool isLeg);

    error NoRouter();
    error Reentrancy();

    uint256 private _lock = 1;
    modifier nonReentrant() {
        if (_lock != 1) revert Reentrancy();
        _lock = 2;
        _;
        _lock = 1;
    }

    constructor(
        address campaign_,
        IPonsV2FeeEscrow escrow_,
        uint16 backerBps_,
        address[] memory legRecipients_,
        uint16[] memory legBps_,
        IEquityRouter equityRouter_
    ) FeeSplitter(campaign_, backerBps_, legRecipients_, legBps_) {
        escrow = escrow_;
        equityRouter = equityRouter_;
    }

    /// claimBacker(address(0)), but the ETH arrives as `key.currency1`.
    /// Same accounting path as the plain claim — effects first, then one
    /// router call — so the two can never disagree about what was owed.
    /// A failed swap reverts the whole tx and the claim stays claimable.
    function claimBackerAs(PoolKey calldata key, uint256 minOut) external nonReentrant returns (uint256 out) {
        if (address(equityRouter) == address(0)) revert NoRouter();
        if (!campaign.launched()) revert NotLaunched();
        distribute(address(0));
        uint256 owed = backerEntitlement(msg.sender, address(0)) - backerClaimed[msg.sender][address(0)];
        if (owed == 0) revert NothingToClaim();
        backerClaimed[msg.sender][address(0)] += owed;
        out = _routeOut(key, minOut, owed, false);
    }

    /// claimLeg(address(0)) routed the same way — a named vault wallet or
    /// the platform can take its share as stock too.
    function claimLegAs(PoolKey calldata key, uint256 minOut) external nonReentrant returns (uint256 out) {
        if (address(equityRouter) == address(0)) revert NoRouter();
        distribute(address(0));
        uint256 owed = legOwed[msg.sender][address(0)];
        if (owed == 0) revert NothingToClaim();
        legOwed[msg.sender][address(0)] = 0;
        out = _routeOut(key, minOut, owed, true);
    }

    function _routeOut(PoolKey calldata key, uint256 minOut, uint256 owed, bool isLeg) internal returns (uint256 out) {
        accounted[address(0)] -= owed; // mirror _pay: accounted shrinks with balance
        uint256 balBefore = address(this).balance;
        out = equityRouter.routeEthTo{value: owed}(key, minOut, msg.sender, "");
        // The router refunds unspent native to its caller — us. It is the
        // claimer's, not the pool's: left here it would be re-distributed
        // to everyone on the next crank. Clamped to what we sent.
        uint256 back = address(this).balance + owed - balBefore;
        if (back > owed) back = owed;
        if (back > 0) {
            (bool ok, ) = msg.sender.call{value: back}("");
            if (!ok) revert EthSend();
        }
        emit ClaimedAs(msg.sender, key.currency1, owed - back, out, isLeg);
    }

    /// Pull everything the escrow owes us, then account. Permissionless.
    function harvest() external {
        // native side (pons pays launch-fee-adjacent flows in ETH even for
        // ERC20-quoted pools; claiming zero-cost when nothing is owed)
        uint256 owedEth = escrow.balanceOf(address(this));
        if (owedEth > 0) escrow.claim(owedEth);
        distribute(address(0));

        address t = ICampaignAssetsView(address(campaign)).token();
        if (t != address(0)) {
            uint256 owedTok = escrow.balanceOfToken(address(this), t);
            if (owedTok > 0) escrow.claimToken(t, owedTok);
            distribute(t);
        }

        address q = ICampaignAssetsView(address(campaign)).quoteToken();
        if (q != address(0)) {
            uint256 owedQ = escrow.balanceOfToken(address(this), q);
            if (owedQ > 0) escrow.claimToken(q, owedQ);
            distribute(q);
        }
    }
}

src/FeeSplitterV4.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC20} from "./interfaces/IPons.sol";
import {IPonsV2FeeEscrow} from "./interfaces/IPonsV2.sol";
import {IEquityRouter} from "./interfaces/IEquityRouter.sol";
import {PoolKey} from "./interfaces/IUniV4.sol";

interface ICampaignHoldView {
    function contributionOf(address backer) external view returns (uint256);
    function totalRaisedAtLaunch() external view returns (uint256);
    function tokensAtLaunch() external view returns (uint256);
    function tokensClaimed(address backer) external view returns (bool);
    function launched() external view returns (bool);
    function token() external view returns (address);
    function quoteToken() external view returns (address);
}

/// FeeSplitterV3 with one new rule: **the fee stream follows the tokens.**
///
/// V1–V3 paid a backer their launch-time share of the creator tax forever,
/// whether or not they still held the token. A wallet that sold in minute
/// one kept earning next to the wallets that stayed. This generation
/// weighs every claim by how much of the launch allocation the wallet
/// still holds, and hands the rest to the holder-rewards leg — the
/// platform token's stakers, once the vault is the leg recipient.
///
///   held   = min(balance, allocation) / allocation      (unclaimed = held)
///   kept   = freshEntitlement × held
///   lost   = freshEntitlement − kept   → legOwed[forfeitTo]
///
/// Entitlement is judged ONCE per unit — `backerSettled` records how much
/// of a backer's lifetime entitlement has already been split into kept and
/// lost, so a settle followed by a claim can never scale the same fees
/// twice. `settle(backer)` is a permissionless crank: anyone can lock in a
/// seller's forfeiture while they are out, which is what makes "buy back
/// just before claiming" a losing trade — the fees that accrued while they
/// were out are already gone. Fees judged while holding are banked and
/// stay theirs even if they sell afterwards: you earned those while in.
///
/// Known edges, stated up front: transferring the allocation to another
/// wallet reads as selling. Held = wallet balance + unclaimed (still in
/// the campaign, including a pre-launch lock) + staked in the rewards
/// vault when this token is the vault's stake token. Buying more than the allocation caps at 100% — it never pays
/// more than the launch-time share.
///
/// Everything else is FeeSplitterV3 verbatim in behaviour — per-asset
/// accounting, pull-based legs, the escrow harvest, and routed claims
/// through EquityRouter. Standalone (not inherited) so no deployed source
/// changes: the V3 claim paths are non-virtual and would bypass the rule.
/// No owner, no pause, no upgrade, no way to change the split.
contract FeeSplitterV4 {
    ICampaignHoldView public immutable campaign;
    IPonsV2FeeEscrow public immutable escrow;
    /// Platform-fixed at construction, never caller-supplied (see V3).
    IEquityRouter public immutable equityRouter;
    /// Where a seller's share goes: the holder-rewards leg recipient.
    address public immutable forfeitTo;
    uint16 public immutable backerBps; // out of 10_000
    address[] public legRecipients;
    uint16[] public legBps;

    mapping(address => uint256) public backerPool;                          // cumulative, per asset
    mapping(address => mapping(address => uint256)) public legOwed;         // leg => asset => unclaimed
    mapping(address => mapping(address => uint256)) public backerClaimed;   // backer => asset => lifetime PAID
    mapping(address => mapping(address => uint256)) public backerSettled;   // backer => asset => entitlement already judged
    mapping(address => mapping(address => uint256)) public backerBanked;    // backer => asset => judged-and-kept, unpaid
    mapping(address => uint256) public accounted;

    event Settled(address indexed backer, address indexed asset, uint256 kept, uint256 forfeited, uint16 heldBps);
    event BackerClaimed(address indexed backer, address indexed asset, uint256 amount);
    event ClaimedAs(address indexed who, address indexed asset, uint256 ethIn, uint256 assetOut, bool isLeg);

    error NotLaunched();
    error NothingToClaim();
    error LengthMismatch();
    error BpsSum();
    error EthSend();
    error NoRouter();
    error Reentrancy();
    error BadForfeit();

    uint256 private _lock = 1;
    modifier nonReentrant() {
        if (_lock != 1) revert Reentrancy();
        _lock = 2;
        _;
        _lock = 1;
    }

    constructor(
        address campaign_,
        IPonsV2FeeEscrow escrow_,
        uint16 backerBps_,
        address[] memory legRecipients_,
        uint16[] memory legBps_,
        IEquityRouter equityRouter_,
        address forfeitTo_
    ) {
        if (legRecipients_.length != legBps_.length) revert LengthMismatch();
        // A zero recipient would strand every forfeited wei: only address(0)
        // could claim it.
        if (forfeitTo_ == address(0)) revert BadForfeit();
        uint256 sum = backerBps_;
        for (uint256 i = 0; i < legBps_.length; i++) sum += legBps_[i];
        if (sum != 10_000) revert BpsSum();
        campaign = ICampaignHoldView(campaign_);
        escrow = escrow_;
        backerBps = backerBps_;
        legRecipients = legRecipients_;
        legBps = legBps_;
        equityRouter = equityRouter_;
        forfeitTo = forfeitTo_;
    }

    receive() external payable {}

    // ── the rule ─────────────────────────────────────────────────────

    /// How much of its launch allocation a backer still holds, in bps.
    /// Tokens not yet claimed sit in the campaign contract — fully held.
    function heldBps(address backer) public view returns (uint16) {
        if (!campaign.tokensClaimed(backer)) return 10_000;
        uint256 total = campaign.totalRaisedAtLaunch();
        if (total == 0) return 10_000;
        uint256 alloc = (campaign.tokensAtLaunch() * campaign.contributionOf(backer)) / total;
        if (alloc == 0) return 10_000;
        address t = campaign.token();
        uint256 bal = IERC20(t).balanceOf(backer) + _stakedInVault(backer, t);
        if (bal >= alloc) return 10_000;
        return uint16((bal * 10_000) / alloc);
    }

    /// Tokens staked in the rewards vault are held, not sold — but only
    /// when THIS campaign's token is the vault's stake token (the platform
    /// token's own raise). The vault is the forfeit recipient; on older
    /// factories that address is an EOA, so this is a raw staticcall that
    /// answers zero for anything that isn't a vault. Views only.
    function _stakedInVault(address backer, address t) internal view returns (uint256) {
        (bool ok, bytes memory d) = forfeitTo.staticcall(abi.encodeWithSignature("stakeToken()"));
        if (!ok || d.length < 32 || abi.decode(d, (address)) != t) return 0;
        (ok, d) = forfeitTo.staticcall(abi.encodeWithSignature("stakedOf(address)", backer));
        if (!ok || d.length < 32) return 0;
        return abi.decode(d, (uint256));
    }

    /// A backer's lifetime entitlement from the backer pool for `asset` —
    /// the launch-time share, before the hold rule. Same as V1–V3.
    function backerEntitlement(address backer, address asset) public view returns (uint256) {
        uint256 total = campaign.totalRaisedAtLaunch();
        if (total == 0) return 0;
        return (backerPool[asset] * campaign.contributionOf(backer)) / total;
    }

    /// What a claim would pay right now: banked + the unjudged remainder at
    /// the current hold. The UI's number. Does not include un-distributed
    /// balance — call distribute() (or read it as pending) for that.
    function backerOwed(address backer, address asset) external view returns (uint256) {
        uint256 fresh = backerEntitlement(backer, asset) - backerSettled[backer][asset];
        return backerBanked[backer][asset] + (fresh * heldBps(backer)) / 10_000;
    }

    /// Judge the not-yet-judged entitlement at the current hold. Returns
    /// what the backer keeps; the rest is now the holder-rewards leg's.
    function _settle(address backer, address asset) internal returns (uint256 kept, uint256 fresh) {
        fresh = backerEntitlement(backer, asset) - backerSettled[backer][asset];
        if (fresh == 0) return (0, 0);
        backerSettled[backer][asset] += fresh;
        uint16 h = heldBps(backer);
        kept = (fresh * h) / 10_000;
        uint256 lost = fresh - kept;
        if (lost > 0) legOwed[forfeitTo][asset] += lost;
        emit Settled(backer, asset, kept, lost, h);
    }

    /// Permissionless crank: lock in a backer's hold-weighted split now.
    /// The kept part is banked for them; the forfeited part is gone. Call
    /// it on a wallet that sold, and the fees that accrued while it was out
    /// can never be recovered by buying back before a claim.
    function settle(address backer, address asset) external nonReentrant {
        if (!campaign.launched()) revert NotLaunched();
        distribute(asset);
        (uint256 kept, ) = _settle(backer, asset);
        if (kept > 0) backerBanked[backer][asset] += kept;
    }

    // ── accounting (V3 verbatim) ──────────────────────────────────────

    /// Campaign-only, launch-tx only: move the launch allocation home.
    function drainTo(address to, address asset) external {
        if (msg.sender != address(campaign)) revert NotLaunched();
        uint256 bal = asset == address(0) ? address(this).balance : IERC20(asset).balanceOf(address(this));
        uint256 unaccounted = bal - accounted[asset];
        if (unaccounted == 0) return;
        if (asset == address(0)) {
            (bool ok, ) = to.call{value: unaccounted}("");
            if (!ok) revert EthSend();
        } else {
            if (!IERC20(asset).transfer(to, unaccounted)) revert EthSend();
        }
    }

    /// Permissionless. Allocates any un-accounted balance of `asset` to the
    /// backer pool and the legs. address(0) = native ETH.
    function distribute(address asset) public {
        uint256 bal = asset == address(0) ? address(this).balance : IERC20(asset).balanceOf(address(this));
        uint256 delta = bal - accounted[asset];
        if (delta == 0) return;
        accounted[asset] = bal;
        uint256 toBackers = (delta * backerBps) / 10_000;
        backerPool[asset] += toBackers;
        uint256 allocated = toBackers;
        for (uint256 i = 0; i < legRecipients.length; i++) {
            uint256 amt = (delta * legBps[i]) / 10_000;
            if (i == legRecipients.length - 1) amt = delta - allocated; // dust absorber
            else allocated += amt;
            legOwed[legRecipients[i]][asset] += amt;
        }
    }

    // ── claims ───────────────────────────────────────────────────────

    /// Pull what the hold rule says is yours. A wallet that sold everything
    /// does NOT revert: its share is judged, forfeited and recorded, and the
    /// call pays nothing — the receipt says where the fees went.
    function claimBacker(address asset) external nonReentrant returns (uint256 paid) {
        if (!campaign.launched()) revert NotLaunched();
        distribute(asset);
        (uint256 kept, uint256 fresh) = _settle(msg.sender, asset);
        paid = backerBanked[msg.sender][asset] + kept;
        if (paid == 0 && fresh == 0) revert NothingToClaim();
        backerBanked[msg.sender][asset] = 0;
        if (paid > 0) {
            backerClaimed[msg.sender][asset] += paid;
            emit BackerClaimed(msg.sender, asset, paid);
            _pay(msg.sender, asset, paid);
        }
    }

    /// claimBacker(address(0)), but the ETH arrives as `key.currency1`.
    function claimBackerAs(PoolKey calldata key, uint256 minOut) external nonReentrant returns (uint256 out) {
        if (address(equityRouter) == address(0)) revert NoRouter();
        if (!campaign.launched()) revert NotLaunched();
        distribute(address(0));
        (uint256 kept, uint256 fresh) = _settle(msg.sender, address(0));
        uint256 paid = backerBanked[msg.sender][address(0)] + kept;
        if (paid == 0 && fresh == 0) revert NothingToClaim();
        backerBanked[msg.sender][address(0)] = 0;
        if (paid == 0) return 0; // judged and forfeited; nothing to route
        backerClaimed[msg.sender][address(0)] += paid;
        emit BackerClaimed(msg.sender, address(0), paid);
        out = _routeOut(key, minOut, paid, false);
    }

    /// Pull a leg's outstanding balance of `asset` (platform, holder
    /// rewards, bots…). Forfeited backer shares arrive here too.
    function claimLeg(address asset) external nonReentrant {
        distribute(asset);
        uint256 owed = legOwed[msg.sender][asset];
        if (owed == 0) revert NothingToClaim();
        legOwed[msg.sender][asset] = 0;
        _pay(msg.sender, asset, owed);
    }

    function claimLegAs(PoolKey calldata key, uint256 minOut) external nonReentrant returns (uint256 out) {
        if (address(equityRouter) == address(0)) revert NoRouter();
        distribute(address(0));
        uint256 owed = legOwed[msg.sender][address(0)];
        if (owed == 0) revert NothingToClaim();
        legOwed[msg.sender][address(0)] = 0;
        out = _routeOut(key, minOut, owed, true);
    }

    function _routeOut(PoolKey calldata key, uint256 minOut, uint256 owed, bool isLeg) internal returns (uint256 out) {
        accounted[address(0)] -= owed;
        uint256 balBefore = address(this).balance;
        out = equityRouter.routeEthTo{value: owed}(key, minOut, msg.sender, "");
        uint256 back = address(this).balance + owed - balBefore;
        if (back > owed) back = owed;
        if (back > 0) {
            (bool ok, ) = msg.sender.call{value: back}("");
            if (!ok) revert EthSend();
        }
        emit ClaimedAs(msg.sender, key.currency1, owed - back, out, isLeg);
    }

    function _pay(address to, address asset, uint256 amount) internal {
        accounted[asset] -= amount;
        if (asset == address(0)) {
            (bool ok, ) = to.call{value: amount}("");
            if (!ok) revert EthSend();
        } else {
            if (!IERC20(asset).transfer(to, amount)) revert EthSend();
        }
    }

    /// Pull everything the escrow owes us, then account. Permissionless.
    function harvest() external {
        uint256 owedEth = escrow.balanceOf(address(this));
        if (owedEth > 0) escrow.claim(owedEth);
        distribute(address(0));
        address t = campaign.token();
        if (t != address(0)) {
            uint256 owedTok = escrow.balanceOfToken(address(this), t);
            if (owedTok > 0) escrow.claimToken(t, owedTok);
            distribute(t);
        }
        address q = campaign.quoteToken();
        if (q != address(0)) {
            uint256 owedQ = escrow.balanceOfToken(address(this), q);
            if (owedQ > 0) escrow.claimToken(q, owedQ);
            distribute(q);
        }
    }

    function legCount() external view returns (uint256) {
        return legRecipients.length;
    }
}

