        CampaignFactoryV4 cf = CampaignFactoryV4(payable(VmContractHelper123(0x7109709ECfa91a80626fF3989D68f67F5b1DD12D).deployCode({_artifact: "src/CampaignFactoryV4.sol:CampaignFactoryV4", _args: encodeArgs69(DeployHelper69.FoundryPpConstructorArgs(
            address(0xFEE), address(0x4EAA), 700, 300,
